var QUESTIONS_INFO = {"total_fichier":127,"publiees":123,"exclues":["T9-010","T9-011","T10-010","T10-013"]};
var QUESTIONS = [{"id":"T1-001","theme":1,"question_fr":"Combien de catégories de signaux routiers (panneaux) le décret sur la signalisation distingue-t-il ?","question_ar":"كم عدد أصناف العلامات المرورية (اللوحات) التي يحدّدها الأمر المتعلق بالإشارات المرورية؟","choix":[{"fr":"4 catégories","ar":"4 أصناف"},{"fr":"6 catégories","ar":"6 أصناف"},{"fr":"10 catégories","ar":"10 أصناف"}],"bonnes":[1],"explication_fr":"Six catégories : danger, priorité, interdiction et fin d'interdiction, obligation et fin d'obligation, arrêt et stationnement, indication.","explication_ar":"ستة أصناف: علامات الخطر، علامات الأولوية، علامات المنع ونهاية المنع، علامات الوجوب ونهاية الوجوب، علامات التوقف والوقوف، وعلامات الإرشاد.","source":"Décret n° 2000-150 du 24 janvier 2000, article 13","image":"q-familles-panneaux.svg"},
{"id":"T1-002","theme":1,"question_fr":"Hors agglomération, à quelle distance environ un panneau de danger est-il placé avant l'endroit dangereux ?","question_ar":"خارج المناطق العمرانية، على أي مسافة تقريبية توضع علامة الخطر قبل المكان الخطير؟","choix":[{"fr":"Environ 50 m","ar":"حوالي 50 م"},{"fr":"Environ 150 m","ar":"حوالي 150 م"},{"fr":"Environ 500 m","ar":"حوالي 500 م"}],"bonnes":[1],"explication_fr":"Hors agglomération, le panneau de danger est placé à environ 150 m du danger (environ 50 m en agglomération). Si la distance est différente, un panonceau l'indique.","explication_ar":"خارج المناطق العمرانية توضع علامة الخطر على بعد 150 م تقريبًا من مكان الخطر (و50 م تقريبًا داخلها). وإذا كانت المسافة مختلفة تُبيَّن بلوحة إضافية.","source":"Décret n° 2000-150, article 17","image":"q-danger-hors-agglo.svg"},
{"id":"T1-003","theme":1,"question_fr":"En agglomération, à quelle distance environ un panneau de danger est-il placé avant le danger ?","question_ar":"داخل المناطق العمرانية، على أي مسافة تقريبية توضع علامة الخطر قبل مكان الخطر؟","choix":[{"fr":"Environ 50 m","ar":"حوالي 50 م"},{"fr":"Environ 150 m","ar":"حوالي 150 م"},{"fr":"Juste à l'endroit du danger","ar":"في مكان الخطر نفسه"}],"bonnes":[0],"explication_fr":"En agglomération, la distance approximative est de 50 m (150 m hors agglomération).","explication_ar":"داخل المناطق العمرانية تكون المسافة التقريبية 50 م (و150 م خارجها).","source":"Décret n° 2000-150, article 17","image":"q-danger-agglo.svg"},
{"id":"T1-004","theme":1,"question_fr":"Que vous impose un panneau de danger ?","question_ar":"ماذا تفرض عليك علامة الخطر؟","choix":[{"fr":"Une vigilance spéciale et un ralentissement adapté au danger","ar":"يقظة خاصة وتخفيض السرعة بحسب نوع الخطر"},{"fr":"Un arrêt obligatoire","ar":"التوقف الوجوبي"},{"fr":"Rien, c'est une simple information","ar":"لا شيء، هي مجرد معلومة"}],"bonnes":[0],"explication_fr":"Les signaux de danger imposent une vigilance spéciale et un ralentissement adapté à la nature du danger signalé.","explication_ar":"علامات الخطر تفرض على مستعملي الطريق يقظة خاصة وتخفيضًا للسرعة يتلاءم مع طبيعة الخطر المشار إليه.","source":"Décret n° 2000-150, article 15","image":"q-panneau-danger.svg"},
{"id":"T1-005","theme":1,"question_fr":"À quoi sert un panonceau (petit panneau rectangulaire placé sous un signal) ?","question_ar":"ما دور اللوحة الإضافية (اللوحة المستطيلة الصغيرة الموضوعة تحت العلامة)؟","choix":[{"fr":"Compléter, préciser ou limiter la signification du signal","ar":"إتمام معنى العلامة أو توضيحه أو تحديده"},{"fr":"Annuler le signal","ar":"إلغاء العلامة"},{"fr":"Indiquer seulement le nom de la ville","ar":"بيان اسم المدينة فقط"}],"bonnes":[0],"explication_fr":"Un panonceau peut compléter, préciser ou limiter la signification d'un signal, par une inscription ou un symbole (distance, catégorie de véhicules…).","explication_ar":"يمكن للوحة الإضافية أن تتمّم معنى العلامة أو توضّحه أو تحدّده، بكتابة أو رمز (مسافة، صنف العربات...).","source":"Décret n° 2000-150, article 14","image":"q-panonceau.svg"},
{"id":"T1-006","theme":1,"question_fr":"À partir d'où une interdiction indiquée par un panneau d'interdiction s'applique-t-elle ?","question_ar":"من أي مكان يبدأ تطبيق المنع الذي تشير إليه علامة منع؟","choix":[{"fr":"À partir du panneau lui-même","ar":"ابتداءً من العلامة نفسها"},{"fr":"100 m après le panneau","ar":"100 م بعد العلامة"},{"fr":"À la prochaine intersection seulement","ar":"عند المفترق الموالي فقط"}],"bonnes":[0],"explication_fr":"Le panneau d'interdiction marque la limite à partir de laquelle l'interdiction doit être observée ; le panneau de fin d'interdiction marque l'endroit où elle cesse.","explication_ar":"علامة المنع تحدد المكان الذي يبدأ منه احترام المنع، وعلامة نهاية المنع تحدد المكان الذي ينتهي فيه.","source":"Décret n° 2000-150, article 23","image":"q-debut-interdiction.svg"},
{"id":"T1-007","theme":1,"question_fr":"Que signifie une ligne longitudinale continue sur la chaussée ?","question_ar":"ماذا يعني الخط الطولي المتواصل على المعبّد؟","choix":[{"fr":"Interdiction de la franchir ou de la chevaucher","ar":"يُمنع اجتيازه أو السير فوقه"},{"fr":"On peut la franchir pour dépasser","ar":"يمكن اجتيازه للتجاوز"},{"fr":"On peut la franchir pour tourner à gauche","ar":"يمكن اجتيازه للانعطاف يسارًا"}],"bonnes":[0],"explication_fr":"Une ligne continue interdit à tout conducteur de la chevaucher ou de la franchir.","explication_ar":"الخط المتواصل يمنع على كل سائق السير فوقه أو اجتيازه.","source":"Décret n° 2000-150, article 33 ; Code de la route (loi 99-71), article 10","image":"q-ligne-continue.svg"},
{"id":"T1-008","theme":1,"question_fr":"Une ligne continue et une ligne discontinue sont tracées côte à côte. La ligne discontinue est de votre côté. Pouvez-vous les franchir pour dépasser ?","question_ar":"خط متواصل وخط متقطع مرسومان جنبًا إلى جنب، والخط المتقطع من جهتك. هل يمكنك اجتيازهما للتجاوز؟","choix":[{"fr":"Oui, car la première ligne à franchir est discontinue","ar":"نعم، لأن الخط الأول الذي ستجتازه متقطع"},{"fr":"Non, jamais","ar":"لا، أبدًا"}],"bonnes":[0],"explication_fr":"Le conducteur ne tient compte que de la ligne qui se trouve de son côté : il peut franchir si la première ligne à franchir est discontinue.","explication_ar":"لا يأخذ السائق بعين الاعتبار إلا الخط الموجود من جهته: يمكنه الاجتياز إذا كان الخط الأول الذي سيجتازه متقطعًا.","source":"Décret n° 2000-150, article 35 ; Code de la route, article 10 (alinéa 3)","image":"q-lignes.svg"},
{"id":"T1-009","theme":1,"question_fr":"Une ligne jaune CONTINUE est peinte sur la bordure du trottoir. Qu'est-ce qui est interdit le long de cette ligne ?","question_ar":"خط أصفر متواصل مرسوم على حافة الرصيف. ما الممنوع على طول هذا الخط؟","choix":[{"fr":"L'arrêt (et donc aussi le stationnement)","ar":"التوقف (وبالتالي الوقوف أيضًا)"},{"fr":"Seulement le stationnement","ar":"الوقوف فقط"},{"fr":"Rien, c'est décoratif","ar":"لا شيء، هو للتزيين"}],"bonnes":[0],"explication_fr":"La ligne jaune continue interdit l'arrêt ; la ligne jaune discontinue interdit le stationnement.","explication_ar":"الخط الأصفر المتواصل يمنع التوقف، والخط الأصفر المتقطع يمنع الوقوف.","source":"Décret n° 2000-150, article 44","image":"q-ligne-jaune-continue.svg"},
{"id":"T1-010","theme":1,"question_fr":"Une ligne jaune DISCONTINUE est peinte au bord de la chaussée. Que signifie-t-elle ?","question_ar":"خط أصفر متقطع مرسوم على حافة المعبّد. ماذا يعني؟","choix":[{"fr":"Stationnement interdit le long de la ligne","ar":"الوقوف ممنوع على طول الخط"},{"fr":"Arrêt et stationnement autorisés","ar":"التوقف والوقوف مسموح بهما"},{"fr":"Voie réservée aux bus","ar":"ممر مخصص للحافلات"}],"bonnes":[0],"explication_fr":"La ligne jaune discontinue interdit le stationnement sur la chaussée le long de cette ligne (la continue interdit l'arrêt).","explication_ar":"الخط الأصفر المتقطع يمنع الوقوف على المعبّد على طول هذا الخط (والمتواصل يمنع التوقف).","source":"Décret n° 2000-150, article 44","image":"q-ligne-jaune-discontinue.svg"},
{"id":"T1-011","theme":1,"question_fr":"Des lignes blanches parallèles ou obliques (zébras) délimitent un îlot ou une zone d'évitement. Que devez-vous faire ?","question_ar":"خطوط بيضاء متوازية أو مائلة تحدد جزيرة توجيه أو منطقة تفادٍ. ماذا يجب أن تفعل؟","choix":[{"fr":"Ne pas y circuler, ni s'y arrêter, ni y stationner","ar":"عدم السير عليها وعدم التوقف أو الوقوف فوقها"},{"fr":"On peut y stationner brièvement","ar":"يمكن الوقوف فوقها لمدة قصيرة"},{"fr":"On peut y rouler pour dépasser","ar":"يمكن السير فوقها للتجاوز"}],"bonnes":[0],"explication_fr":"Les conducteurs ne doivent ni circuler, ni s'arrêter, ni stationner sur ces marques.","explication_ar":"يجب على السائقين عدم السير أو التوقف أو الوقوف على هذه العلامات.","source":"Décret n° 2000-150, article 43","image":"q-zebras.svg"},
{"id":"T1-012","theme":1,"question_fr":"Des flèches blanches légèrement courbées (flèches de rabattement) apparaissent entre les traits d'une ligne discontinue. Qu'annoncent-elles ?","question_ar":"أسهم بيضاء منحنية قليلًا (أسهم الرجوع) تظهر بين أجزاء خط متقطع. بماذا تُنذر؟","choix":[{"fr":"La ligne discontinue va devenir continue : il faut se rabattre","ar":"الخط المتقطع سيصبح متواصلًا: يجب الرجوع إلى اليمين"},{"fr":"Le début d'une autoroute","ar":"بداية طريق سيارة"},{"fr":"Un parking","ar":"موقف سيارات"}],"bonnes":[0],"explication_fr":"Situées dans les intervalles d'une ligne discontinue, les flèches de rabattement signifient que cette ligne va devenir continue ; dans une voie, elles annoncent sa suppression.","explication_ar":"إذا كانت أسهم الرجوع بين أجزاء خط متقطع فهي تعني أن هذا الخط سيصبح متواصلًا، وإذا كانت داخل ممر فهي تُنذر بإلغائه.","source":"Décret n° 2000-150, article 38","image":"q-fleches-rabattement.svg"},
{"id":"T1-013","theme":1,"question_fr":"Un agent de la circulation lève un bras verticalement. Que signifie ce geste ?","question_ar":"عون تنظيم المرور يرفع ذراعه عموديًا. ماذا تعني هذه الإشارة؟","choix":[{"fr":"« Attention, arrêt » pour tous les usagers","ar":"«انتباه، قف» لكل مستعملي الطريق"},{"fr":"Passage libre pour tous","ar":"المرور مسموح للجميع"},{"fr":"Arrêt seulement pour les piétons","ar":"التوقف للمترجلين فقط"}],"bonnes":[0],"explication_fr":"Le bras levé verticalement signifie « attention, arrêt » pour tous les usagers, sauf pour ceux qui ne pourraient plus s'arrêter en sécurité ; il n'impose pas l'arrêt aux conducteurs déjà engagés dans l'intersection.","explication_ar":"الذراع المرفوعة عموديًا تعني «انتباه، قف» لكل المستعملين، إلا لمن لم يعد بإمكانه التوقف في ظروف آمنة، ولا تفرض التوقف على من دخل المفترق.","source":"Décret n° 2000-150, article 3","image":"q-agent-bras-leve.svg"},
{"id":"T1-014","theme":1,"question_fr":"Un agent règle la circulation à un carrefour où le feu est vert pour vous. L'agent vous fait signe de vous arrêter. Que faites-vous ?","question_ar":"عون يُنظم المرور في مفترق والضوء أخضر بالنسبة إليك، والعون يشير إليك بالتوقف. ماذا تفعل؟","choix":[{"fr":"Je m'arrête : les indications de l'agent priment sur les feux","ar":"أتوقف: إشارات العون لها الأولوية على الأضواء"},{"fr":"Je passe car le feu est vert","ar":"أمرّ لأن الضوء أخضر"}],"bonnes":[0],"explication_fr":"Ordre de priorité : indications des agents, puis signaux lumineux (sauf orange clignotant), puis autres signaux routiers.","explication_ar":"ترتيب الأولوية: إشارات الأعوان، ثم الإشارات الضوئية (عدا البرتقالي المتقطع)، ثم بقية العلامات المرورية.","source":"Code de la route, article 45 ; Décret n° 2000-150, article 4","image":"q-agent-feu-vert.svg"},
{"id":"T1-015","theme":1,"question_fr":"Une voie délimitée par de larges traits porte l'inscription « BUS ». Un automobiliste ordinaire peut-il l'emprunter ?","question_ar":"ممر محدد بخطوط عريضة ومكتوب عليه «BUS». هل يمكن لسائق سيارة عادية استعماله؟","choix":[{"fr":"Non, sauf pour la traverser à une intersection ou pour entrer/sortir d'une propriété riveraine","ar":"لا، إلا لاجتيازه في مفترق أو للدخول إلى ملك مجاور أو الخروج منه"},{"fr":"Oui, s'il est pressé","ar":"نعم، إذا كان مستعجلًا"},{"fr":"Oui, la nuit seulement","ar":"نعم، في الليل فقط"}],"bonnes":[0],"explication_fr":"Cette voie est réservée aux transports publics réguliers (et aux taxis si « TAXI » est ajouté) ; les autres véhicules ne la franchissent qu'à une intersection ou pour accéder à une propriété riveraine ou la quitter.","explication_ar":"هذا الممر مخصص لوسائل النقل العمومي المنتظم (وسيارات الأجرة إذا أُضيفت كلمة TAXI)، ولا تجتازه بقية العربات إلا في مفترق أو للدخول إلى ملك مجاور أو الخروج منه.","source":"Décret n° 2000-150, article 41","image":"q-voie-bus.svg"},
{"id":"T1-016","theme":1,"question_fr":"Vous voyez un panneau rond à fond blanc bordé de rouge portant le chiffre « 50 ». Que signifie-t-il ?","question_ar":"ترى علامة دائرية ذات خلفية بيضاء وإطار أحمر عليها الرقم «50». ماذا تعني؟","choix":[{"fr":"Vitesse limitée à 50 km/h à partir du panneau","ar":"السرعة محددة بـ 50 كم/س ابتداءً من العلامة"},{"fr":"Vitesse minimale de 50 km/h","ar":"سرعة دنيا 50 كم/س"},{"fr":"Distance de 50 m avant un danger","ar":"مسافة 50 م قبل خطر"}],"bonnes":[0],"explication_fr":"C'est un panneau d'interdiction (catégorie C) : limitation de vitesse. L'interdiction s'applique à partir du panneau.","explication_ar":"هي علامة منع (الصنف C): تحديد السرعة، ويبدأ تطبيق المنع من مكان العلامة.","source":"Décret n° 2000-150, articles 13, 23 et 25 (annexe C)","image":"q-panneau-50.svg"},
{"id":"T2-001","theme":2,"question_fr":"Deux voitures arrivent en même temps à une intersection sans signalisation, venant de routes différentes. Qui doit céder le passage ?","question_ar":"سيارتان تصلان في نفس الوقت إلى مفترق بدون إشارات، قادمتان من طريقين مختلفين. من يجب أن يترك الأولوية؟","choix":[{"fr":"Le conducteur qui vient de la gauche","ar":"السائق القادم من اليسار"},{"fr":"Le conducteur qui vient de la droite","ar":"السائق القادم من اليمين"},{"fr":"Le véhicule le plus lent","ar":"العربة الأبطأ"}],"bonnes":[0],"explication_fr":"Règle de la priorité à droite : le conducteur venant de la gauche doit céder le passage à l'autre conducteur.","explication_ar":"قاعدة الأولوية لليمين: السائق القادم من اليسار ملزم بترك المرور للسائق الآخر.","source":"Code de la route (loi 99-71), article 28 (alinéa 1)","image":"q-intersection.svg"},
{"id":"T2-002","theme":2,"question_fr":"Vous circulez sur une route signalée comme prioritaire. Une voiture arrive par votre droite. Qui passe en premier ?","question_ar":"تسير على طريق مُشار إليها بأنها ذات أولوية، وسيارة تأتي من يمينك. من يمر أولًا؟","choix":[{"fr":"Moi, car je suis sur la route prioritaire signalée","ar":"أنا، لأنني على الطريق ذات الأولوية المُشار إليها"},{"fr":"La voiture de droite","ar":"السيارة القادمة من اليمين"}],"bonnes":[0],"explication_fr":"Par exception à la priorité à droite, la priorité appartient au conducteur qui circule sur une route prioritaire indiquée par des signaux réglementaires.","explication_ar":"استثناءً من الأولوية لليمين، تكون الأولوية للسائق الذي يسير على طريق ذات أولوية مُشار إليها بعلامات قانونية.","source":"Code de la route, article 28 (alinéa 2)","image":"q-route-prioritaire.svg"},
{"id":"T2-003","theme":2,"question_fr":"Vous arrivez à un carrefour à sens giratoire annoncé par la signalisation. À qui devez-vous céder le passage ?","question_ar":"تصل إلى مفترق دائري مُعلن عنه بالإشارات. لمن يجب أن تترك المرور؟","choix":[{"fr":"Aux usagers qui circulent déjà dans l'anneau","ar":"لمستعملي الطريق الذين يسيرون داخل الحلقة"},{"fr":"Aux véhicules qui veulent entrer à ma droite","ar":"للعربات التي تريد الدخول من يميني"},{"fr":"À personne, j'ai la priorité","ar":"لا أحد، الأولوية لي"}],"bonnes":[0],"explication_fr":"Avant d'entrer dans un giratoire signalé, tout conducteur cède le passage aux usagers circulant à l'intérieur, quel que soit le classement de la route qu'il quitte.","explication_ar":"قبل الدخول إلى مفترق دائري مُشار إليه، يترك كل سائق المرور لمستعملي الطريق الذين يسيرون داخله، مهما كان تصنيف الطريق التي يغادرها.","source":"Décret n° 2000-150, article 20","image":"q-giratoire.svg"},
{"id":"T2-004","theme":2,"question_fr":"Vous arrivez à une intersection avec un panneau « STOP ». Que devez-vous faire ?","question_ar":"تصل إلى مفترق به علامة «قف» (STOP). ماذا يجب أن تفعل؟","choix":[{"fr":"M'arrêter à la limite de la chaussée, puis passer seulement si c'est sans danger","ar":"أتوقف عند حدّ المعبّد، ثم أمرّ فقط إذا كان ذلك دون خطر"},{"fr":"Ralentir et passer si personne ne vient","ar":"أخفّض السرعة وأمرّ إذا لم يأتِ أحد"},{"fr":"Klaxonner et passer","ar":"أستعمل المنبه وأمرّ"}],"bonnes":[0],"explication_fr":"Au signal STOP, l'arrêt est obligatoire à la limite de la chaussée abordée ; on ne s'y engage qu'après s'être assuré de pouvoir le faire sans danger.","explication_ar":"عند علامة «قف» يكون التوقف وجوبيًا عند حدّ المعبّد الذي تقترب منه، ولا تدخله إلا بعد التأكد من إمكانية ذلك دون خطر.","source":"Code de la route, article 29","image":"q-stop.svg"},
{"id":"T2-005","theme":2,"question_fr":"Une ambulance arrive derrière vous avec son avertisseur spécial et son feu bleu allumés. Que faites-vous ?","question_ar":"سيارة إسعاف قادمة خلفك وهي تستعمل منبّهها الخاص وضوءها الأزرق. ماذا تفعل؟","choix":[{"fr":"Je libère la chaussée et, si nécessaire, je m'arrête pour la laisser passer","ar":"أُخلي الطريق وأتوقف عند الحاجة لتمكينها من المرور"},{"fr":"Je continue normalement","ar":"أواصل السير بشكل عادي"},{"fr":"J'accélère pour rester devant","ar":"أزيد في السرعة لأبقى أمامها"}],"bonnes":[0],"explication_fr":"Tout conducteur doit céder le passage aux véhicules prioritaires et d'intervention urgente (ambulances) qui annoncent leur approche par leurs signaux spéciaux, en libérant la chaussée ou en s'arrêtant.","explication_ar":"يجب على كل سائق أن يترك المرور للعربات ذات الأولوية وعربات التدخل العاجل (سيارات الإسعاف) التي تعلن عن قدومها بإشاراتها الخاصة، بإخلاء الطريق أو بالتوقف.","source":"Code de la route, article 30 ; Décret n° 2000-149, articles 6 et 7","image":"q-ambulance-derriere.svg"},
{"id":"T2-006","theme":2,"question_fr":"Quelle est la couleur du feu tournant d'une ambulance (véhicule d'intervention urgente) ?","question_ar":"ما لون الضوء الدوّار لسيارة الإسعاف (عربة تدخل عاجل)؟","choix":[{"fr":"Bleu","ar":"أزرق"},{"fr":"Rouge","ar":"أحمر"},{"fr":"Orange","ar":"برتقالي"}],"bonnes":[0],"explication_fr":"Les véhicules d'intervention urgente (ambulances) ont un feu tournant bleu ; les véhicules prioritaires (militaires, forces de sécurité intérieure) ont un feu tournant rouge.","explication_ar":"عربات التدخل العاجل (سيارات الإسعاف) مجهزة بضوء دوّار أزرق، أما العربات ذات الأولوية (العسكرية وقوات الأمن الداخلي) فمجهزة بضوء دوّار أحمر.","source":"Décret n° 2000-149, articles 2, 4, 6 et 7","image":"q-gyrophare.svg"},
{"id":"T2-007","theme":2,"question_fr":"Le feu est vert, mais l'intersection est bloquée par des voitures et vous ne pourrez pas la dégager. Que faites-vous ?","question_ar":"الضوء أخضر لكن المفترق مزدحم بالسيارات ولن تتمكن من الخروج منه. ماذا تفعل؟","choix":[{"fr":"J'attends avant l'intersection","ar":"أنتظر قبل المفترق"},{"fr":"Je m'engage car le feu est vert","ar":"أدخل لأن الضوء أخضر"}],"bonnes":[0],"explication_fr":"On ne doit pas s'engager dans une intersection si la congestion empêche de la dégager et gêne les autres sens, même avec la priorité donnée par un feu ou un panneau.","explication_ar":"لا يجوز الدخول إلى مفترق إذا كان الازدحام يمنع الخروج منه ويعرقل حركة الاتجاهات الأخرى، حتى ولو كانت لك الأولوية بضوء أو بعلامة.","source":"Code de la route, article 27","image":"q-carrefour-bloque.svg"},
{"id":"T2-008","theme":2,"question_fr":"Vous sortez d'un parking privé (ou d'un chemin non goudronné) pour entrer sur une route. Qui a la priorité ?","question_ar":"تخرج من موقف خاص (أو من مسلك غير معبّد) للدخول إلى طريق. لمن الأولوية؟","choix":[{"fr":"Les véhicules qui circulent sur la route","ar":"العربات التي تسير على الطريق"},{"fr":"Moi, s'ils viennent de ma gauche","ar":"أنا، إذا كانوا قادمين من يساري"}],"bonnes":[0],"explication_fr":"Tout conducteur qui débouche d'une propriété riveraine, d'un chemin non bitumé, ou qui repart après un arrêt ou un stationnement, cède le passage aux véhicules circulant sur la chaussée.","explication_ar":"كل سائق يخرج من ملك مجاور للطريق أو من مسلك غير معبّد أو يستأنف السير بعد توقف أو وقوف، يترك المرور للعربات التي تسير على المعبّد.","source":"Code de la route, article 31","image":"q-sortie-parking.svg"},
{"id":"T2-009","theme":2,"question_fr":"Que signifie un feu orange FIXE ?","question_ar":"ماذا يعني الضوء البرتقالي الثابت؟","choix":[{"fr":"Interdiction de franchir la ligne d'arrêt, sauf si l'on est trop près pour s'arrêter en sécurité","ar":"يُمنع اجتياز خط التوقف، إلا إذا كنت قريبًا جدًا ولا يمكنك التوقف بأمان"},{"fr":"Accélérer pour passer avant le rouge","ar":"زيادة السرعة للمرور قبل الأحمر"},{"fr":"Passer avec prudence, les priorités normales s'appliquent","ar":"المرور بحذر مع تطبيق قواعد الأولوية العادية"}],"bonnes":[0],"explication_fr":"Le feu orange fixe interdit de franchir la ligne d'arrêt, sauf si, au moment où il s'allume, le conducteur est si près qu'il ne peut plus s'arrêter en sécurité.","explication_ar":"الضوء البرتقالي الثابت يمنع اجتياز خط التوقف، إلا إذا كان السائق، عند اشتعاله، قريبًا جدًا بحيث لا يمكنه التوقف في ظروف آمنة.","source":"Décret n° 2000-150, article 5 (point 2)","image":"q-feu-orange.svg"},
{"id":"T2-010","theme":2,"question_fr":"Le feu orange CLIGNOTE à un carrefour. Que devez-vous faire ?","question_ar":"الضوء البرتقالي متقطع (يومض) في مفترق. ماذا يجب أن تفعل؟","choix":[{"fr":"Passer en redoublant de prudence en appliquant les règles de priorité normales (panneaux, priorité à droite)","ar":"المرور بمزيد من الحذر مع تطبيق قواعد الأولوية العادية (العلامات، الأولوية لليمين)"},{"fr":"S'arrêter comme au feu rouge","ar":"التوقف كما عند الضوء الأحمر"},{"fr":"Passer : j'ai toujours la priorité","ar":"المرور: لي الأولوية دائمًا"}],"bonnes":[0],"explication_fr":"Le feu orange clignotant autorise le passage en redoublant de prudence et ne modifie pas les règles de priorité : les règles générales s'appliquent.","explication_ar":"الضوء البرتقالي المتقطع يسمح بالمرور مع مضاعفة الحذر ولا يغيّر قواعد الأولوية: تُطبَّق القواعد العامة.","source":"Décret n° 2000-150, article 11 ; Code de la route, article 45","image":"q-orange-clignotant.svg"},
{"id":"T2-011","theme":2,"question_fr":"Le feu est rouge, mais une flèche verte vers la droite est allumée à côté. Que pouvez-vous faire ?","question_ar":"الضوء أحمر، لكن سهمًا أخضر نحو اليمين مضاء بجانبه. ماذا يمكنك أن تفعل؟","choix":[{"fr":"Tourner à droite en cédant le passage aux autres conducteurs et aux piétons","ar":"الانعطاف يمينًا مع ترك المرور للسائقين الآخرين وللمترجلين"},{"fr":"Aller tout droit","ar":"المواصلة إلى الأمام"},{"fr":"Rien, je dois attendre le vert","ar":"لا شيء، يجب أن أنتظر الأخضر"}],"bonnes":[0],"explication_fr":"Une flèche verte allumée avec le feu rouge autorise à continuer seulement dans la direction de la flèche, en cédant le passage aux conducteurs venant régulièrement d'autres directions et aux piétons.","explication_ar":"السهم الأخضر المضاء مع الضوء الأحمر يسمح بمواصلة السير في اتجاه السهم فقط، مع ترك المرور للسائقين القادمين بصفة قانونية من اتجاهات أخرى وللمترجلين.","source":"Décret n° 2000-150, article 5 (point 5)","image":"q-feu-fleche.svg"},
{"id":"T2-012","theme":2,"question_fr":"Vous tournez à gauche à une intersection. À qui devez-vous céder le passage pendant la manœuvre ? (plusieurs réponses)","question_ar":"تنعطف يسارًا في مفترق. لمن يجب أن تترك المرور أثناء المناورة؟ (عدة إجابات)","choix":[{"fr":"Aux véhicules venant en sens inverse","ar":"للعربات القادمة من الاتجاه المعاكس"},{"fr":"Aux piétons qui traversent la route où je m'engage","ar":"للمترجلين الذين يعبرون الطريق التي أدخلها"},{"fr":"Aux cycles sur une piste cyclable qui traverse cette route","ar":"للدراجات على مسلك الدراجات الذي يقطع تلك الطريق"},{"fr":"À personne","ar":"لا أحد"}],"bonnes":[0,1,2],"explication_fr":"En changeant de direction, on cède le passage aux véhicules venant en sens inverse (sauf indication contraire), aux cycles sur les pistes cyclables traversées et aux piétons qui traversent.","explication_ar":"عند تغيير الاتجاه يجب ترك المرور للعربات القادمة من الاتجاه المعاكس (ما لم تكن هناك إشارة مخالفة)، وللدراجات على المسالك المخصصة لها، وللمترجلين الذين يعبرون.","source":"Code de la route, article 26","image":"q-tourner-gauche.svg"},
{"id":"T2-013","theme":2,"question_fr":"Deux feux rouges clignotent alternativement à un passage à niveau. Que devez-vous faire ?","question_ar":"ضوءان أحمران يومضان بالتناوب عند ممر على السكة الحديدية. ماذا يجب أن تفعل؟","choix":[{"fr":"M'arrêter : interdiction de franchir la ligne d'arrêt ou le signal","ar":"أتوقف: يُمنع اجتياز خط التوقف أو الإشارة"},{"fr":"Passer vite avant le train","ar":"أمر بسرعة قبل القطار"},{"fr":"Passer avec prudence","ar":"أمر بحذر"}],"bonnes":[0],"explication_fr":"Deux feux rouges clignotant alternativement à un passage à niveau interdisent à tous les usagers de franchir la ligne d'arrêt (ou le signal). La priorité appartient au train.","explication_ar":"الضوءان الأحمران الوامضان بالتناوب عند ممر على السكة يمنعان كل المستعملين من اجتياز خط التوقف (أو الإشارة). والأولوية للقطار.","source":"Décret n° 2000-150, article 11 ; Code de la route, article 32","image":"q-passage-niveau-feux.svg"},
{"id":"T3-001","theme":3,"question_fr":"De quel côté se font le croisement et le dépassement ?","question_ar":"من أي جهة يتم الالتقاء (المقابلة) والتجاوز؟","choix":[{"fr":"Croisement à droite, dépassement à gauche","ar":"الالتقاء على اليمين والتجاوز على اليسار"},{"fr":"Croisement à gauche, dépassement à droite","ar":"الالتقاء على اليسار والتجاوز على اليمين"},{"fr":"Les deux à droite","ar":"الاثنان على اليمين"}],"bonnes":[0],"explication_fr":"Le croisement s'effectue à droite et le dépassement à gauche.","explication_ar":"الالتقاء يكون على اليمين والتجاوز على اليسار.","source":"Code de la route, article 16","image":"q-croisement-depassement.svg"},
{"id":"T3-002","theme":3,"question_fr":"Quelle distance latérale minimale devez-vous laisser pour dépasser un cycliste ?","question_ar":"ما المسافة الجانبية الدنيا التي يجب تركها لتجاوز راكب دراجة؟","choix":[{"fr":"50 cm","ar":"50 صم"},{"fr":"1 m","ar":"1 م"},{"fr":"20 cm","ar":"20 صم"}],"bonnes":[1],"explication_fr":"Au moins 1 m pour dépasser un piéton, un véhicule à traction animale, un animal, un cycle ou un motocycle à deux roues ; au moins 50 cm pour les autres véhicules.","explication_ar":"مترًا واحدًا على الأقل لتجاوز مترجل أو عربة مجرورة بحيوان أو حيوان أو دراجة أو دراجة نارية ذات عجلتين، و50 صم على الأقل لبقية العربات.","source":"Décret n° 2000-151, article 14","image":"q-cycliste.svg"},
{"id":"T3-003","theme":3,"question_fr":"Quelle distance latérale minimale devez-vous laisser pour dépasser une autre voiture ?","question_ar":"ما المسافة الجانبية الدنيا لتجاوز سيارة أخرى؟","choix":[{"fr":"50 cm","ar":"50 صم"},{"fr":"1 m","ar":"1 م"},{"fr":"2 m","ar":"2 م"}],"bonnes":[0],"explication_fr":"Pour les véhicules autres que piétons, animaux, cycles et deux-roues motorisés, la distance latérale minimale est de 50 cm.","explication_ar":"بالنسبة للعربات الأخرى (غير المترجلين والحيوانات والدراجات والدراجات النارية ذات العجلتين) تكون المسافة الجانبية الدنيا 50 صم.","source":"Décret n° 2000-151, article 14","image":"q-depasser-voiture.svg"},
{"id":"T3-004","theme":3,"question_fr":"Quand le dépassement par la DROITE est-il autorisé ?","question_ar":"متى يُسمح بالتجاوز من اليمين؟","choix":[{"fr":"Quand le conducteur devant a annoncé ou entamé un changement de direction vers la gauche","ar":"عندما يكون السائق الذي أمامك قد أعلن أو بدأ انعطافًا نحو اليسار"},{"fr":"Quand le conducteur devant roule lentement","ar":"عندما يسير السائق الذي أمامك ببطء"},{"fr":"Jamais","ar":"أبدًا"}],"bonnes":[0],"explication_fr":"Par exception, on peut dépasser à droite un véhicule dont le conducteur a annoncé ou entamé un changement de direction vers la gauche, en respectant les précautions de l'article 19.","explication_ar":"استثناءً، يمكن تجاوز عربة من اليمين إذا أعلن سائقها أو بدأ تغيير الاتجاه نحو اليسار، مع احترام الاحتياطات الواردة في الفصل 19.","source":"Code de la route, article 21","image":"q-depasser-droite.svg"},
{"id":"T3-005","theme":3,"question_fr":"Un véhicule est en train de vous dépasser. Que devez-vous faire ?","question_ar":"عربة بصدد تجاوزك. ماذا يجب أن تفعل؟","choix":[{"fr":"Serrer à droite et ne pas augmenter ma vitesse","ar":"ألتزم أقصى اليمين ولا أزيد في سرعتي"},{"fr":"Accélérer pour l'empêcher","ar":"أزيد في السرعة لمنعه"},{"fr":"Freiner brusquement","ar":"أفرمل فجأة"}],"bonnes":[0],"explication_fr":"Le conducteur sur le point d'être dépassé doit serrer à son extrême droite et ne pas augmenter sa vitesse.","explication_ar":"السائق الذي سيقع تجاوزه يجب أن يلتزم أقصى يمينه وألا يزيد في سرعته.","source":"Code de la route, article 20","image":"q-etre-depasse.svg"},
{"id":"T3-006","theme":3,"question_fr":"Dans quels cas est-il interdit de dépasser une voiture ? (plusieurs réponses)","question_ar":"في أي حالات يُمنع تجاوز سيارة؟ (عدة إجابات)","choix":[{"fr":"À l'approche d'un sommet de côte","ar":"عند الاقتراب من قمة مرتفع"},{"fr":"Dans un virage","ar":"في منعرج"},{"fr":"Sur un passage à niveau sans barrières","ar":"على ممر سكة حديدية بدون حواجز"},{"fr":"Sur une ligne droite bien dégagée, sans signalisation contraire","ar":"في طريق مستقيمة واضحة بدون علامات مانعة"}],"bonnes":[0,1,2],"explication_fr":"Le dépassement des véhicules (autres que cycles et deux-roues) est interdit notamment : là où des signaux l'interdisent, à l'approche des sommets de côte, dans les virages, quand la visibilité est insuffisante, aux passages à niveau sans barrières, sur les ponts étroits (2 voies max), aux intersections (sauf sur route prioritaire signalée).","explication_ar":"يُمنع تجاوز العربات (غير الدراجات والدراجات النارية ذات العجلتين) خاصة: حيث تمنعه العلامات، عند الاقتراب من قمم المرتفعات، في المنعرجات، عند عدم كفاية الرؤية، في الممرات على السكة بدون حواجز، على الجسور الضيقة (ممران على الأكثر)، وفي المفترقات (إلا على طريق ذات أولوية مُشار إليها).","source":"Décret n° 2000-151, article 15 ; Code de la route, article 18","image":"q-cas-depassement.svg"},
{"id":"T3-007","theme":3,"question_fr":"Sur une route à double sens qui comporte TROIS voies matérialisées, quelle voie utilisez-vous pour dépasser ?","question_ar":"في طريق ذات اتجاهين بها ثلاثة ممرات مرسومة، أي ممر تستعمل للتجاوز؟","choix":[{"fr":"Exclusivement la voie centrale","ar":"الممر الأوسط فقط"},{"fr":"La voie de gauche","ar":"الممر الأيسر"},{"fr":"N'importe laquelle","ar":"أي ممر"}],"bonnes":[0],"explication_fr":"Sur une chaussée à double sens comportant trois voies matérialisées, le conducteur qui dépasse doit emprunter exclusivement la voie centrale.","explication_ar":"في معبّد ذي اتجاهين به ثلاثة ممرات مرسومة، يجب على السائق الذي يتجاوز أن يستعمل الممر الأوسط فقط.","source":"Décret n° 2000-151, article 14 (dernier alinéa)","image":"q-trois-voies.svg"},
{"id":"T3-008","theme":3,"question_fr":"Sur une route en forte pente, le croisement est difficile. Qui doit céder le passage ?","question_ar":"في طريق شديدة الانحدار يصعب الالتقاء. من يجب أن يترك المرور؟","choix":[{"fr":"Le véhicule qui descend cède au véhicule qui monte","ar":"العربة النازلة تترك المرور للعربة الصاعدة"},{"fr":"Le véhicule qui monte cède au véhicule qui descend","ar":"العربة الصاعدة تترك المرور للعربة النازلة"}],"bonnes":[0],"explication_fr":"Lorsque le croisement est difficile sur une route à forte déclivité, les véhicules descendants cèdent le passage aux véhicules montants.","explication_ar":"عندما يكون الالتقاء صعبًا في طريق شديدة الانحدار، تترك العربات النازلة المرور للعربات الصاعدة.","source":"Décret n° 2000-151, article 16 (point 2)","image":"q-forte-pente.svg"},
{"id":"T3-009","theme":3,"question_fr":"Sur une route étroite, une voiture et un camion se font face et l'un doit faire marche arrière. Qui doit reculer ?","question_ar":"في طريق ضيقة تتقابل سيارة وشاحنة ويجب على أحدهما الرجوع إلى الخلف. من يرجع؟","choix":[{"fr":"La voiture (véhicule léger)","ar":"السيارة (العربة الخفيفة)"},{"fr":"Le camion (véhicule lourd)","ar":"الشاحنة (العربة الثقيلة)"}],"bonnes":[0],"explication_fr":"Si le croisement nécessite une marche arrière, elle s'impose au véhicule léger par rapport au véhicule lourd (et au véhicule isolé par rapport à l'ensemble de véhicules, au camion par rapport à l'autocar).","explication_ar":"إذا تطلّب الالتقاء الرجوع إلى الخلف، يُفرض ذلك على العربة الخفيفة مقارنة بالثقيلة (وعلى العربة المنفردة مقارنة بمجموعة العربات، وعلى الشاحنة مقارنة بالحافلة).","source":"Décret n° 2000-151, article 16 (point 3)","image":"q-route-etroite.svg"},
{"id":"T3-010","theme":3,"question_fr":"Avant de commencer un dépassement, que devez-vous vérifier ? (plusieurs réponses)","question_ar":"قبل الشروع في التجاوز، ماذا يجب أن تتأكد منه؟ (عدة إجابات)","choix":[{"fr":"Que la voie est libre sur une distance suffisante","ar":"أن الطريق خالية على مسافة كافية"},{"fr":"Que le conducteur qui me suit n'a pas commencé à me dépasser","ar":"أن السائق الذي خلفي لم يشرع في تجاوزي"},{"fr":"Que je pourrai reprendre ma file sans danger","ar":"أنني سأتمكن من الرجوع إلى مساري دون خطر"},{"fr":"Que je n'ai pas besoin d'avertir les autres","ar":"أنني لست في حاجة إلى تنبيه الآخرين"}],"bonnes":[0,1,2],"explication_fr":"Avant de dépasser : vérifier qu'aucune interdiction ne s'applique, que la voie est libre sur une distance suffisante, que ni le conducteur devant ni celui derrière n'ont commencé un dépassement, qu'on pourra se rabattre sans danger, et avertir les autres usagers.","explication_ar":"قبل التجاوز: التأكد من عدم وجود حالة منع، ومن أن الطريق خالية على مسافة كافية، ومن أن السائق الذي أمامك والذي خلفك لم يشرعا في تجاوز، ومن إمكانية الرجوع إلى المسار دون خطر، مع تنبيه بقية المستعملين.","source":"Code de la route, article 19","image":"q-avant-depasser.svg"},
{"id":"T3-011","theme":3,"question_fr":"Sur une route à plusieurs voies dans le même sens, la circulation est dense et se fait en files parallèles. Une file avance plus vite que la vôtre. S'agit-il d'un dépassement ?","question_ar":"في طريق بها عدة ممرات في نفس الاتجاه، والحركة كثيفة وتسير في صفوف متوازية. صفّ يتقدم أسرع من صفّك. هل يُعتبر ذلك تجاوزًا؟","choix":[{"fr":"Non, ce n'est pas considéré comme un dépassement","ar":"لا، لا يُعتبر تجاوزًا"},{"fr":"Oui, c'est un dépassement par la droite interdit","ar":"نعم، هو تجاوز ممنوع من اليمين"}],"bonnes":[0],"explication_fr":"Quand la circulation se fait en files parallèles, le fait qu'une file roule plus vite qu'une autre n'est pas considéré comme un dépassement.","explication_ar":"عندما تسير الحركة في صفوف متوازية، لا يُعتبر تجاوزًا كون صفّ يسير أسرع من صفّ آخر.","source":"Code de la route, article 22","image":"q-files-paralleles.svg"},
{"id":"T3-012","theme":3,"question_fr":"Vous conduisez un véhicule lent sur une route étroite et des véhicules plus rapides vous suivent. Que devez-vous faire ?","question_ar":"تسوق عربة بطيئة في طريق ضيقة وخلفك عربات أسرع. ماذا يجب أن تفعل؟","choix":[{"fr":"Serrer à l'extrême droite, utiliser l'accotement ou m'arrêter dès que possible pour les laisser passer","ar":"ألتزم أقصى اليمين وأستعمل الحاشية أو أتوقف في أقرب وقت لأتركها تمر"},{"fr":"Rouler au milieu pour les empêcher de dépasser","ar":"أسير في الوسط لمنعها من التجاوز"}],"bonnes":[0],"explication_fr":"Les conducteurs circulant à vitesse réduite doivent serrer à l'extrême droite et, si besoin, utiliser l'accotement ou s'arrêter pour laisser passer ceux qui les suivent.","explication_ar":"يجب على السائقين الذين يسيرون بسرعة منخفضة الالتزام بأقصى اليمين، وعند الحاجة استعمال الحاشية أو التوقف لترك المرور لمن خلفهم.","source":"Code de la route, article 23","image":"q-vehicule-lent.svg"},
{"id":"T4-001","theme":4,"question_fr":"Quelle est la vitesse maximale en agglomération (règle générale) ?","question_ar":"ما هي السرعة القصوى داخل المناطق العمرانية (القاعدة العامة)؟","choix":[{"fr":"50 km/h","ar":"50 كم/س"},{"fr":"60 km/h","ar":"60 كم/س"},{"fr":"70 km/h","ar":"70 كم/س"}],"bonnes":[0],"explication_fr":"En agglomération, la vitesse est limitée à 50 km/h. Le président de la commune peut la réduire à 30 km/h ; le ministre de l'Équipement peut la porter à 70 km/h sur certaines routes.","explication_ar":"داخل المناطق العمرانية تُحدد السرعة بـ 50 كم/س. ويمكن لرئيس البلدية تخفيضها إلى 30 كم/س، ويمكن لوزير التجهيز رفعها إلى 70 كم/س في بعض الطرق.","source":"Décret n° 2000-151, article 5","image":"q-vitesse-agglo.svg"},
{"id":"T4-002","theme":4,"question_fr":"Vous conduisez une voiture particulière (moins de 3,5 t) hors agglomération, sur une route ordinaire, par beau temps. Vitesse maximale ?","question_ar":"تسوق سيارة خاصة (أقل من 3,5 طن) خارج المناطق العمرانية، على طريق عادية، والطقس جيد. ما السرعة القصوى؟","choix":[{"fr":"80 km/h","ar":"80 كم/س"},{"fr":"90 km/h","ar":"90 كم/س"},{"fr":"110 km/h","ar":"110 كم/س"}],"bonnes":[1],"explication_fr":"Hors agglomération (hors autoroute), la limite est de 90 km/h pour les véhicules dont le poids total autorisé en charge ne dépasse pas 3 500 kg.","explication_ar":"خارج المناطق العمرانية (عدا الطريق السيارة) تُحدد السرعة بـ 90 كم/س للعربات التي لا يتجاوز وزنها الجملي المرخص فيه بالحمولة 3500 كغ.","source":"Décret n° 2000-151, article 6","image":"q-vitesse-route.svg"},
{"id":"T4-003","theme":4,"question_fr":"Quelle est la vitesse maximale d'une voiture particulière sur autoroute (beau temps, conducteur hors période de stage) ?","question_ar":"ما السرعة القصوى لسيارة خاصة على الطريق السيارة (طقس جيد، سائق خارج فترة التربص)؟","choix":[{"fr":"100 km/h","ar":"100 كم/س"},{"fr":"110 km/h","ar":"110 كم/س"},{"fr":"130 km/h","ar":"130 كم/س"}],"bonnes":[1],"explication_fr":"Sur autoroute, 110 km/h pour les motocyclettes et les véhicules de 3 500 kg au plus.","explication_ar":"على الطريق السيارة: 110 كم/س للدراجات النارية والعربات التي لا يتجاوز وزنها 3500 كغ.","source":"Décret n° 2000-151, article 7","image":"q-vitesse-autoroute.svg"},
{"id":"T4-004","theme":4,"question_fr":"En circulation normale sur autoroute, quelle est la vitesse MINIMALE ?","question_ar":"في الحركة العادية على الطريق السيارة، ما هي السرعة الدنيا؟","choix":[{"fr":"40 km/h","ar":"40 كم/س"},{"fr":"60 km/h","ar":"60 كم/س"},{"fr":"Il n'y a pas de vitesse minimale","ar":"لا توجد سرعة دنيا"}],"bonnes":[1],"explication_fr":"En circulation normale sur autoroute, la vitesse minimale ne doit pas être inférieure à 60 km/h.","explication_ar":"في الحركة العادية على الطريق السيارة، يجب ألا تقل السرعة عن 60 كم/س.","source":"Décret n° 2000-151, article 7 (dernier alinéa)","image":"q-vitesse-mini-autoroute.svg"},
{"id":"T4-005","theme":4,"question_fr":"Il pleut fort et la visibilité est réduite. Vous roulez en voiture sur autoroute. Quelle est votre vitesse maximale ?","question_ar":"تمطر بغزارة والرؤية منخفضة، وأنت تسوق سيارة على الطريق السيارة. ما سرعتك القصوى؟","choix":[{"fr":"110 km/h","ar":"110 كم/س"},{"fr":"100 km/h","ar":"100 كم/س"},{"fr":"90 km/h","ar":"90 كم/س"}],"bonnes":[2],"explication_fr":"Quand la visibilité est réduite (pluie, brouillard…), les limites sont réduites de 20 km/h sur autoroute et hors agglomération, et de 10 km/h en agglomération : 110 − 20 = 90 km/h.","explication_ar":"عند انخفاض الرؤية (مطر، ضباب...) تُخفَّض السرعات القصوى بـ 20 كم/س على الطرق السيارة وخارج المناطق العمرانية، وبـ 10 كم/س داخلها: 110 − 20 = 90 كم/س.","source":"Décret n° 2000-151, articles 7 et 8","image":"q-pluie-autoroute.svg"},
{"id":"T4-006","theme":4,"question_fr":"Par temps de brouillard, en agglomération (limite habituelle 50 km/h), quelle est la vitesse maximale ?","question_ar":"في الضباب داخل منطقة عمرانية (السرعة المعتادة 50 كم/س)، ما السرعة القصوى؟","choix":[{"fr":"30 km/h","ar":"30 كم/س"},{"fr":"40 km/h","ar":"40 كم/س"},{"fr":"50 km/h","ar":"50 كم/س"}],"bonnes":[1],"explication_fr":"En agglomération, la réduction en cas de visibilité réduite est de 10 km/h : 50 − 10 = 40 km/h.","explication_ar":"داخل المناطق العمرانية يكون التخفيض عند انخفاض الرؤية 10 كم/س: 50 − 10 = 40 كم/س.","source":"Décret n° 2000-151, articles 5 et 8","image":"q-brouillard-agglo.svg"},
{"id":"T4-007","theme":4,"question_fr":"Vous avez votre permis depuis 6 mois (période de stage). Quelle est votre vitesse maximale sur autoroute ?","question_ar":"تحصّلت على رخصتك منذ 6 أشهر (فترة التربص). ما سرعتك القصوى على الطريق السيارة؟","choix":[{"fr":"80 km/h","ar":"80 كم/س"},{"fr":"90 km/h","ar":"90 كم/س"},{"fr":"110 km/h","ar":"110 كم/س"}],"bonnes":[0],"explication_fr":"Pendant la période de stage de 2 ans après l'obtention du permis, le conducteur ne doit pas dépasser 80 km/h sur autoroute et hors agglomération.","explication_ar":"خلال فترة التربص (سنتان من تاريخ الحصول على الرخصة)، لا يجوز للسائق تجاوز 80 كم/س على الطرق السيارة وخارج المناطق العمرانية.","source":"Code de la route, article 82 ; Décret n° 2000-151, article 12","image":"q-jeune-conducteur.svg"},
{"id":"T4-008","theme":4,"question_fr":"Combien de temps dure la période de stage d'un nouveau conducteur ?","question_ar":"كم تدوم فترة التربص للسائق الجديد؟","choix":[{"fr":"1 an","ar":"سنة واحدة"},{"fr":"2 ans","ar":"سنتان"},{"fr":"3 ans","ar":"3 سنوات"}],"bonnes":[1],"explication_fr":"Les nouveaux titulaires du permis sont soumis à une période de stage de deux ans à compter de la date d'obtention du permis.","explication_ar":"يخضع المتحصلون الجدد على رخصة السياقة لفترة تربص مدتها سنتان من تاريخ الحصول عليها.","source":"Code de la route, article 82","image":"q-periode-stage.svg"},
{"id":"T4-009","theme":4,"question_fr":"Quelle est la vitesse maximale d'un cyclomoteur ?","question_ar":"ما هي السرعة القصوى للدراجة النارية الصغيرة (cyclomoteur)؟","choix":[{"fr":"30 km/h","ar":"30 كم/س"},{"fr":"40 km/h","ar":"40 كم/س"},{"fr":"50 km/h","ar":"50 كم/س"}],"bonnes":[1],"explication_fr":"Le conducteur d'un cyclomoteur ne doit pas dépasser 40 km/h.","explication_ar":"لا يجوز لسائق الدراجة النارية الصغيرة تجاوز 40 كم/س.","source":"Décret n° 2000-151, article 9","image":"q-cyclomoteur.svg"},
{"id":"T4-010","theme":4,"question_fr":"Que dit la loi sur la distance entre votre véhicule et celui qui vous précède ?","question_ar":"ماذا يقول القانون عن المسافة بين عربتك والعربة التي أمامك؟","choix":[{"fr":"Elle doit être suffisante pour éviter la collision si le véhicule devant freine brusquement ou s'arrête","ar":"يجب أن تكون كافية لتفادي الاصطدام إذا فرملت العربة التي أمامك فجأة أو توقفت"},{"fr":"Elle n'est obligatoire que sur autoroute","ar":"هي وجوبية على الطريق السيارة فقط"},{"fr":"Il n'y a aucune règle","ar":"لا توجد أي قاعدة"}],"bonnes":[0],"explication_fr":"Tout conducteur doit laisser une distance de sécurité suffisante pour éviter la collision en cas de brusque réduction de vitesse ou d'arrêt imprévu du véhicule qui le précède.","explication_ar":"يجب على كل سائق ترك مسافة أمان كافية لتفادي الاصطدام في حالة تخفيض مفاجئ للسرعة أو توقف غير متوقع للعربة التي أمامه.","source":"Code de la route, article 14","image":"q-distance-securite.svg"},
{"id":"T4-011","theme":4,"question_fr":"Dans quelles situations devez-vous réduire sensiblement votre vitesse ? (plusieurs réponses)","question_ar":"في أي حالات يجب أن تُخفّض سرعتك بشكل ملحوظ؟ (عدة إجابات)","choix":[{"fr":"À l'approche d'un passage pour piétons","ar":"عند الاقتراب من ممر المترجلين"},{"fr":"À l'approche d'un sommet de côte","ar":"عند الاقتراب من قمة مرتفع"},{"fr":"À proximité d'une école","ar":"بالقرب من مدرسة"},{"fr":"Sur une autoroute dégagée par beau temps","ar":"على طريق سيارة خالية والطقس جيد"}],"bonnes":[0,1,2],"explication_fr":"Il faut réduire sensiblement sa vitesse notamment : visibilité insuffisante, virages et descentes, approche des intersections, des sommets de côte, des passages pour piétons, des arrêts de transport ; et près des écoles (au besoin s'arrêter).","explication_ar":"يجب تخفيض السرعة بشكل ملحوظ خاصة عند: عدم كفاية الرؤية، المنعرجات والمنحدرات، الاقتراب من المفترقات وقمم المرتفعات وممرات المترجلين ومحطات النقل، وبالقرب من المدارس (مع التوقف عند الحاجة).","source":"Décret n° 2000-151, articles 3 et 4 ; Code de la route, article 13","image":"q-ralentir.svg"},
{"id":"T5-001","theme":5,"question_fr":"Quelle est la différence entre « arrêt » et « stationnement » ?","question_ar":"ما الفرق بين «التوقف» و«الوقوف»؟","choix":[{"fr":"L'arrêt est une immobilisation momentanée (montée/descente, chargement) avec le conducteur à proximité ; le stationnement est une immobilisation moteur arrêté pour d'autres raisons","ar":"التوقف هو توقيف وقتي (صعود ونزول الأشخاص، شحن وتفريغ) مع بقاء السائق قرب العربة؛ والوقوف هو توقيف العربة مع إيقاف المحرك لأسباب أخرى"},{"fr":"Il n'y a aucune différence","ar":"لا فرق بينهما"},{"fr":"L'arrêt dure plus longtemps que le stationnement","ar":"التوقف أطول من الوقوف"}],"bonnes":[0],"explication_fr":"Arrêt : immobilisation momentanée pour la montée/descente de personnes ou le chargement/déchargement, le conducteur restant aux commandes ou à proximité. Stationnement : immobilisation avec arrêt du moteur pour d'autres raisons.","explication_ar":"التوقف: توقيف وقتي لصعود الأشخاص ونزولهم أو لشحن البضائع وتفريغها مع بقاء السائق في مكانه أو قرب العربة. الوقوف: توقيف العربة مع إيقاف المحرك لأسباب أخرى.","source":"Code de la route, article 3 (définitions)","image":"q-arret-stationnement.svg"},
{"id":"T5-002","theme":5,"question_fr":"À partir de combien de jours un stationnement au même endroit est-il considéré comme « abusif » ?","question_ar":"ابتداءً من كم يومًا يُعتبر الوقوف في نفس المكان «وقوفًا تعسفيًا»؟","choix":[{"fr":"Plus de 3 jours","ar":"أكثر من 3 أيام"},{"fr":"Plus de 7 jours","ar":"أكثر من 7 أيام"},{"fr":"Plus de 30 jours","ar":"أكثر من 30 يومًا"}],"bonnes":[1],"explication_fr":"Est abusif tout stationnement continu au même endroit pendant plus de sept jours.","explication_ar":"يُعتبر تعسفيًا كل وقوف متواصل في نفس المكان لمدة تتجاوز سبعة أيام.","source":"Code de la route, article 39","image":"q-stationnement-abusif.svg"},
{"id":"T5-003","theme":5,"question_fr":"En agglomération, sur une route à double sens, comment devez-vous vous garer ?","question_ar":"داخل منطقة عمرانية، في طريق ذات اتجاهين، كيف يجب أن تقف؟","choix":[{"fr":"Du côté droit, dans le sens de la circulation, à 30 cm au plus du trottoir","ar":"على الجهة اليمنى، في اتجاه السير، على بعد 30 صم على الأكثر من الرصيف"},{"fr":"Du côté gauche, face à la circulation","ar":"على الجهة اليسرى، في الاتجاه المعاكس"},{"fr":"N'importe où, s'il y a de la place","ar":"في أي مكان إذا توفر فضاء"}],"bonnes":[0],"explication_fr":"En agglomération, l'arrêt/stationnement se fait dans le sens de la circulation, à 30 cm au plus du trottoir, sur la partie droite d'une route à double sens (droite ou gauche sur une route à sens unique).","explication_ar":"داخل المناطق العمرانية يكون التوقف والوقوف في اتجاه السير، على بعد لا يتجاوز 30 صم من الرصيف، على الجهة اليمنى في الطريق ذات الاتجاهين (اليمنى أو اليسرى في الطريق ذات الاتجاه الواحد).","source":"Décret n° 2000-151, article 18","image":"q-se-garer-double-sens.svg"},
{"id":"T5-004","theme":5,"question_fr":"Hors agglomération, où devez-vous vous arrêter ou stationner si l'accotement est assez large et n'est pas réservé aux piétons ?","question_ar":"خارج المناطق العمرانية، أين يجب أن تتوقف أو تقف إذا كانت الحاشية عريضة بما يكفي وغير مخصصة للمترجلين؟","choix":[{"fr":"Sur l'accotement","ar":"على الحاشية"},{"fr":"Sur la chaussée","ar":"على المعبّد"},{"fr":"Au milieu de la route avec les feux de détresse","ar":"وسط الطريق مع أضواء الخطر"}],"bonnes":[0],"explication_fr":"Hors agglomération, l'arrêt et le stationnement se font sur l'accotement s'il n'est pas utilisé par les piétons et s'il est assez large. Ils sont interdits sur la chaussée sans emplacement aménagé.","explication_ar":"خارج المناطق العمرانية يكون التوقف والوقوف على الحاشية إذا لم تكن مستعملة من المترجلين وكانت عريضة بما يكفي، ويُمنعان على المعبّد إذا لم تكن به أماكن مهيأة لذلك.","source":"Décret n° 2000-151, article 19","image":"q-accotement.svg"},
{"id":"T5-005","theme":5,"question_fr":"En agglomération, à quelle distance minimale d'une intersection pouvez-vous vous arrêter ou stationner ?","question_ar":"داخل منطقة عمرانية، على أي مسافة دنيا من مفترق يمكنك التوقف أو الوقوف؟","choix":[{"fr":"3 m","ar":"3 م"},{"fr":"10 m","ar":"10 م"},{"fr":"30 m","ar":"30 م"}],"bonnes":[0],"explication_fr":"L'arrêt ou le stationnement est dangereux à moins de 3 m d'une intersection en agglomération et de 10 m hors agglomération (mesurés depuis la ligne de raccordement du trottoir).","explication_ar":"يُعتبر التوقف أو الوقوف خطيرًا على بعد أقل من 3 م من المفترق داخل المناطق العمرانية و10 م خارجها (انطلاقًا من خط التقاء الرصيف).","source":"Décret n° 2000-151, article 20 (point 3)","image":"q-arret-intersection.svg"},
{"id":"T5-006","theme":5,"question_fr":"Hors agglomération, à quelle distance minimale d'un passage à niveau peut-on s'arrêter ou stationner ?","question_ar":"خارج المناطق العمرانية، على أي مسافة دنيا من ممر السكة الحديدية يمكن التوقف أو الوقوف؟","choix":[{"fr":"10 m","ar":"10 م"},{"fr":"30 m","ar":"30 م"},{"fr":"100 m","ar":"100 م"}],"bonnes":[1],"explication_fr":"Arrêt ou stationnement dangereux sur les passages à niveau et à moins de 30 m hors agglomération (10 m en agglomération).","explication_ar":"يُعتبر التوقف أو الوقوف خطيرًا على ممرات السكة وعلى بعد أقل من 30 م منها خارج المناطق العمرانية (10 م داخلها).","source":"Décret n° 2000-151, article 20 (point 4)","image":"q-arret-passage-niveau.svg"},
{"id":"T5-007","theme":5,"question_fr":"Pourquoi est-il interdit de s'arrêter dans un virage où la visibilité est inférieure à 50 m ?","question_ar":"لماذا يُمنع التوقف في منعرج تقل فيه الرؤية عن 50 م؟","choix":[{"fr":"C'est un arrêt dangereux : les autres usagers ne voient pas le véhicule à temps","ar":"هو توقف خطير: لا يرى بقية المستعملين العربة في الوقت المناسب"},{"fr":"Ce n'est pas interdit","ar":"ليس ممنوعًا"}],"bonnes":[0],"explication_fr":"Est dangereux l'arrêt ou le stationnement aux sommets de côte et dans les virages quand la visibilité n'est pas assurée à 50 m au moins dans les deux sens.","explication_ar":"يُعتبر خطيرًا التوقف أو الوقوف في قمم المرتفعات وفي المنعرجات إذا لم تكن الرؤية مضمونة على 50 م على الأقل في الاتجاهين.","source":"Décret n° 2000-151, article 20 (point 1)","image":"q-virage-visibilite.svg"},
{"id":"T5-008","theme":5,"question_fr":"Lesquels de ces stationnements sont considérés comme gênants (donc interdits) ? (plusieurs réponses)","question_ar":"أيّ من حالات الوقوف هذه تُعتبر معرقلة (وبالتالي ممنوعة)؟ (عدة إجابات)","choix":[{"fr":"Sur le trottoir","ar":"على الرصيف"},{"fr":"En double file","ar":"في صف ثانٍ"},{"fr":"Devant l'entrée d'un garage","ar":"أمام مدخل مستودع"},{"fr":"Le long du trottoir, à droite, à moins de 30 cm, sans signalisation contraire","ar":"على طول الرصيف، على اليمين، على أقل من 30 صم، دون علامة مانعة"}],"bonnes":[0,1,2],"explication_fr":"Sont notamment gênants : sur les trottoirs, sur les passages pour piétons, en double file, devant les entrées de propriétés et de parkings, près des bouches d'incendie, en masquant les panneaux.","explication_ar":"تُعتبر معرقلة خاصة: الوقوف على الأرصفة، على ممرات المترجلين، في صف ثانٍ، أمام مداخل الأملاك والمآوي، قرب حنفيات الإطفاء، أو بشكل يحجب العلامات.","source":"Décret n° 2000-151, articles 21 et 22","image":"q-stationnements-genants.svg"},
{"id":"T5-009","theme":5,"question_fr":"Hors intersection, à quelle distance d'un passage pour piétons le stationnement est-il considéré comme gênant ?","question_ar":"خارج المفترقات، على أي مسافة من ممر المترجلين يُعتبر الوقوف معرقلًا؟","choix":[{"fr":"À moins de 5 m","ar":"على أقل من 5 م"},{"fr":"À moins de 20 m","ar":"على أقل من 20 م"},{"fr":"À moins de 50 m","ar":"على أقل من 50 م"}],"bonnes":[1],"explication_fr":"Le stationnement à moins de 20 m d'un passage pour piétons situé hors intersection est gênant. (Au niveau d'une intersection : à moins de 3 m.) L'arrêt et le stationnement SUR le passage sont toujours interdits.","explication_ar":"الوقوف على أقل من 20 م من ممر مترجلين خارج المفترق يُعتبر معرقلًا (وعلى أقل من 3 م إذا كان الممر في مستوى المفترق). والتوقف والوقوف فوق الممر ممنوعان دائمًا.","source":"Décret n° 2000-151, articles 21 et 22 ; Décret n° 2000-150, article 40","image":"q-arret-passage-pietons.svg"},
{"id":"T5-010","theme":5,"question_fr":"Dans une rue à stationnement unilatéral alterné, à quelle heure change-t-on de côté (sauf décision contraire de la commune) ?","question_ar":"في نهج يكون فيه الوقوف من جهة واحدة بالتداول، في أي ساعة يتم تغيير الجهة (ما لم تقرر البلدية خلاف ذلك)؟","choix":[{"fr":"Entre 20 h 30 et 21 h","ar":"بين الساعة 20:30 و21:00"},{"fr":"À minuit","ar":"عند منتصف الليل"},{"fr":"À 8 h du matin","ar":"على الساعة 8 صباحًا"}],"bonnes":[0],"explication_fr":"Sauf dispositions contraires signalées, le changement de côté se fait chaque jour entre 20 h 30 et 21 h.","explication_ar":"ما لم تكن هناك أحكام مخالفة مُشار إليها، يتم تغيير جهة الوقوف يوميًا بين الساعة 20:30 والساعة 21:00.","source":"Décret n° 2000-151, article 23","image":"q-stationnement-alterne.svg"},
{"id":"T5-011","theme":5,"question_fr":"Avant d'ouvrir votre portière pour descendre, que devez-vous faire ?","question_ar":"قبل فتح باب سيارتك للنزول، ماذا يجب أن تفعل؟","choix":[{"fr":"M'assurer que je peux le faire sans danger (cyclistes, voitures)","ar":"أتأكد من أنني أستطيع ذلك دون خطر (دراجات، سيارات)"},{"fr":"Rien de particulier","ar":"لا شيء خاص"}],"bonnes":[0],"explication_fr":"Il est interdit au conducteur ou à un passager de descendre ou d'ouvrir une portière avant de s'être assuré qu'il peut le faire sans danger.","explication_ar":"يُمنع على السائق أو المرافق النزول من العربة أو فتح أحد أبوابها قبل التأكد من إمكانية ذلك دون خطر.","source":"Code de la route, article 41","image":"q-ouvrir-portiere.svg"},
{"id":"T5-012","theme":5,"question_fr":"Sur autoroute, pouvez-vous vous arrêter sur la bande d'arrêt d'urgence pour téléphoner ou vous reposer ?","question_ar":"على الطريق السيارة، هل يمكنك التوقف على شريط التوقف الاستعجالي للهاتف أو للراحة؟","choix":[{"fr":"Non, seulement en cas de nécessité absolue","ar":"لا، فقط في حالة الضرورة القصوى"},{"fr":"Oui, à tout moment","ar":"نعم، في أي وقت"}],"bonnes":[0],"explication_fr":"Sur autoroute, l'arrêt et le stationnement sur les chaussées et accotements, notamment la bande d'arrêt d'urgence, sont interdits sauf nécessité absolue.","explication_ar":"على الطريق السيارة يُمنع التوقف والوقوف على المعبّدات والحواشي، وخاصة شريط التوقف الاستعجالي، إلا في حالة الضرورة القصوى.","source":"Décret n° 2000-151, article 48 ; Code de la route, article 85 (point 2)","image":"q-bande-arret-urgence.svg"},
{"id":"T6-001","theme":6,"question_fr":"Quand l'usage des feux du véhicule est-il obligatoire ?","question_ar":"متى يكون استعمال أضواء العربة وجوبيًا؟","choix":[{"fr":"Du coucher du soleil au lever du jour, et le jour quand la visibilité l'exige","ar":"من غروب الشمس إلى طلوع النهار، وفي النهار عندما تتطلب الرؤية ذلك"},{"fr":"Seulement en agglomération","ar":"داخل المناطق العمرانية فقط"},{"fr":"Seulement quand il pleut","ar":"عند نزول المطر فقط"}],"bonnes":[0],"explication_fr":"Les feux réglementaires sont obligatoires entre le coucher du soleil et le lever du jour, et pendant le jour chaque fois que la visibilité l'exige.","explication_ar":"استعمال الأضواء القانونية وجوبي بين غروب الشمس وطلوع النهار، وفي النهار كلما تطلبت ظروف الرؤية ذلك.","source":"Code de la route, article 42 ; Décret n° 2000-151, article 25","image":"q-feux-obligatoires.svg"},
{"id":"T6-002","theme":6,"question_fr":"La nuit, hors agglomération, vous roulez en feux de route. Une voiture arrive en face. Que faites-vous ?","question_ar":"في الليل خارج المناطق العمرانية تستعمل أضواء الطريق (الأضواء الطويلة)، وسيارة قادمة من الاتجاه المقابل. ماذا تفعل؟","choix":[{"fr":"Je passe en feux de croisement pour ne pas l'éblouir","ar":"أستعمل أضواء التقاطع (القصيرة) حتى لا أبهره"},{"fr":"Je garde les feux de route","ar":"أحتفظ بأضواء الطريق"},{"fr":"J'éteins tous mes feux","ar":"أطفئ كل الأضواء"}],"bonnes":[0],"explication_fr":"Les feux de croisement doivent être utilisés lors du croisement si les feux de route éblouissent le conducteur venant en sens inverse.","explication_ar":"يجب استعمال أضواء التقاطع عند الالتقاء إذا كانت أضواء الطريق تبهر السائق القادم من الاتجاه المعاكس.","source":"Décret n° 2000-151, article 27 (point 1)","image":"q-feux-nuit.svg"},
{"id":"T6-003","theme":6,"question_fr":"La nuit, vous suivez une autre voiture de près sans la dépasser. Quels feux utilisez-vous ?","question_ar":"في الليل تسير خلف سيارة أخرى دون تجاوزها. أي أضواء تستعمل؟","choix":[{"fr":"Les feux de croisement","ar":"أضواء التقاطع"},{"fr":"Les feux de route","ar":"أضواء الطريق"},{"fr":"Les feux de détresse","ar":"أضواء الخطر"}],"bonnes":[0],"explication_fr":"En suivant un véhicule, on utilise les feux de croisement si les feux de route éblouissent son conducteur (sauf pendant le dépassement).","explication_ar":"عند السير خلف عربة تُستعمل أضواء التقاطع إذا كانت أضواء الطريق تبهر سائقها (إلا أثناء التجاوز).","source":"Décret n° 2000-151, article 27 (point 2)","image":"q-suivre-nuit.svg"},
{"id":"T6-004","theme":6,"question_fr":"La nuit, vous roulez dans une rue bien éclairée en continu. Quels feux utilisez-vous ?","question_ar":"في الليل تسير في نهج مضاء بصفة متواصلة. أي أضواء تستعمل؟","choix":[{"fr":"Les feux de croisement","ar":"أضواء التقاطع"},{"fr":"Les feux de route","ar":"أضواء الطريق"},{"fr":"Aucun feu","ar":"لا أضواء"}],"bonnes":[0],"explication_fr":"Les feux de croisement sont obligatoires lorsque l'éclairage de la route est continu et permet de voir sur une distance suffisante.","explication_ar":"تُستعمل أضواء التقاطع عندما تكون إنارة الطريق متواصلة وتسمح بالرؤية على مسافة كافية.","source":"Décret n° 2000-151, article 27 (point 3)","image":"q-rue-eclairee.svg"},
{"id":"T6-005","theme":6,"question_fr":"Par épais brouillard, par quels feux pouvez-vous remplacer les feux de croisement, si votre véhicule en est équipé ?","question_ar":"في الضباب الكثيف، بأي أضواء يمكنك تعويض أضواء التقاطع إذا كانت عربتك مجهزة بها؟","choix":[{"fr":"Les feux de brouillard","ar":"أضواء الضباب"},{"fr":"Les feux de route","ar":"أضواء الطريق"},{"fr":"Les feux de position seuls","ar":"أضواء الموقع فقط"}],"bonnes":[0],"explication_fr":"En cas de réduction notable de la visibilité due au climat, les feux de croisement peuvent être remplacés par les feux de brouillard.","explication_ar":"عند انخفاض الرؤية بشكل ملحوظ بسبب الأحوال الجوية، يمكن تعويض أضواء التقاطع بأضواء الضباب.","source":"Décret n° 2000-151, article 27 (dernier alinéa)","image":"q-brouillard.svg"},
{"id":"T6-006","theme":6,"question_fr":"La nuit, vous stationnez hors agglomération. Quels feux devez-vous laisser allumés ?","question_ar":"في الليل تقف خارج منطقة عمرانية. أي أضواء يجب أن تبقى مشتعلة؟","choix":[{"fr":"Les feux de position (ou de stationnement)","ar":"أضواء الموقع (أو أضواء الوقوف)"},{"fr":"Les feux de route","ar":"أضواء الطريق"},{"fr":"Aucun","ar":"لا شيء"}],"bonnes":[0],"explication_fr":"Les feux de position (ou de stationnement) sont obligatoires pour l'arrêt ou le stationnement la nuit hors agglomération, et en agglomération s'il n'y a pas d'éclairage public.","explication_ar":"أضواء الموقع (أو أضواء الوقوف) وجوبية عند التوقف أو الوقوف ليلًا خارج المناطق العمرانية، وداخلها إذا لم تكن هناك إنارة عمومية.","source":"Décret n° 2000-151, article 26","image":"q-stationner-nuit.svg"},
{"id":"T6-007","theme":6,"question_fr":"Un motocycliste (vélomoteur ou motocyclette) roule en plein jour. Quels feux doit-il allumer ?","question_ar":"سائق دراجة نارية يسير في وضح النهار. أي أضواء يجب أن يشعل؟","choix":[{"fr":"Le feu de croisement et le feu de position arrière","ar":"ضوء التقاطع وضوء الموقع الخلفي"},{"fr":"Aucun feu le jour","ar":"لا أضواء في النهار"},{"fr":"Le feu de route","ar":"ضوء الطريق"}],"bonnes":[0],"explication_fr":"Les conducteurs de vélomoteurs et de motocyclettes doivent utiliser pendant le jour les feux de croisement et les feux de position arrière.","explication_ar":"يجب على سائقي الدراجات النارية استعمال أضواء التقاطع وأضواء الموقع الخلفية في النهار.","source":"Décret n° 2000-151, article 31","image":"q-moto-jour.svg"},
{"id":"T6-008","theme":6,"question_fr":"La nuit, comment devez-vous avertir un autre usager (hors nécessité absolue) ?","question_ar":"في الليل، كيف يجب أن تنبّه مستعملًا آخر للطريق (خارج حالة الضرورة القصوى)؟","choix":[{"fr":"Par des appels lumineux brefs (feux de route ou de croisement)","ar":"بإشارات ضوئية قصيرة (أضواء الطريق أو التقاطع)"},{"fr":"Par un long coup de klaxon","ar":"بضغطة طويلة على المنبه الصوتي"}],"bonnes":[0],"explication_fr":"Entre le coucher du soleil et le lever du jour, seuls les signaux lumineux sont autorisés (feux de route ou de croisement de façon intermittente et brève) ; le klaxon seulement en cas de nécessité absolue.","explication_ar":"بين غروب الشمس وطلوع النهار لا يُسمح إلا بالإشارات الضوئية (أضواء الطريق أو التقاطع بصفة متقطعة وقصيرة)، ولا يُستعمل المنبه الصوتي إلا عند الضرورة القصوى.","source":"Code de la route, article 36","image":"q-avertir-nuit.svg"},
{"id":"T6-009","theme":6,"question_fr":"En agglomération, quand pouvez-vous utiliser le klaxon ?","question_ar":"داخل المناطق العمرانية، متى يمكنك استعمال المنبه الصوتي؟","choix":[{"fr":"Seulement pour éviter un accident","ar":"فقط لتفادي حادث"},{"fr":"Pour saluer un ami","ar":"لتحية صديق"},{"fr":"Quand la voiture devant démarre lentement","ar":"عندما تنطلق السيارة التي أمامك ببطء"}],"bonnes":[0],"explication_fr":"À l'intérieur des agglomérations, les avertisseurs sonores ne doivent être utilisés que pour éviter un accident ; leur usage doit être bref et modéré.","explication_ar":"داخل المناطق العمرانية لا يُستعمل المنبه الصوتي إلا لتفادي حادث، ويجب أن يكون استعماله قصيرًا ومعتدلًا.","source":"Code de la route, articles 33 et 35","image":"q-klaxon-ville.svg"},
{"id":"T6-010","theme":6,"question_fr":"Les feux de croisement doivent éclairer la route sur quelle distance environ (la nuit, par temps clair) ?","question_ar":"على أي مسافة تقريبية يجب أن تضيء أضواء التقاطع الطريق (ليلًا والطقس صافٍ)؟","choix":[{"fr":"Environ 30 m","ar":"حوالي 30 م"},{"fr":"Environ 100 m","ar":"حوالي 100 م"},{"fr":"Environ 300 m","ar":"حوالي 300 م"}],"bonnes":[0],"explication_fr":"Les feux de croisement éclairent environ 30 m sans éblouir ; les feux de route éclairent au minimum 100 m.","explication_ar":"تضيء أضواء التقاطع حوالي 30 م دون إبهار، بينما تضيء أضواء الطريق 100 م على الأقل.","source":"Décret n° 2000-147, articles 55 et 56","image":"q-portee-feux.svg"},
{"id":"T6-011","theme":6,"question_fr":"Comment obtient-on les « feux de détresse » ?","question_ar":"كيف يتم تشغيل «أضواء الخطر» (أضواء الاستغاثة)؟","choix":[{"fr":"En faisant clignoter en même temps tous les indicateurs de changement de direction","ar":"بتشغيل كل أضواء تغيير الاتجاه (الغمازات) في نفس الوقت"},{"fr":"En allumant les feux de route","ar":"بإشعال أضواء الطريق"},{"fr":"En allumant les feux de brouillard arrière","ar":"بإشعال أضواء الضباب الخلفية"}],"bonnes":[0],"explication_fr":"Les feux de détresse consistent à actionner simultanément les indicateurs de changement de direction ; ils peuvent compléter le triangle pour signaler un véhicule en panne.","explication_ar":"أضواء الخطر تتمثل في تشغيل كل مؤشرات تغيير الاتجاه في نفس الوقت، ويمكن استعمالها إضافة إلى المثلث للإشارة إلى عربة معطّبة.","source":"Décret n° 2000-147, article 63 ; Décret n° 2000-151, article 43","image":"q-feux-detresse.svg"},
{"id":"T7-001","theme":7,"question_fr":"À partir de quel taux d'alcool dans le sang un conducteur est-il considéré « sous l'empire d'un état alcoolique » ?","question_ar":"ابتداءً من أي نسبة كحول في الدم يُعتبر السائق «في حالة سكر»؟","choix":[{"fr":"0,3 g/l","ar":"0,3 غ/ل"},{"fr":"0,5 g/l","ar":"0,5 غ/ل"},{"fr":"0,8 g/l","ar":"0,8 غ/ل"}],"bonnes":[0],"explication_fr":"Depuis le décret gouvernemental n° 2016-292 du 1er mars 2016, un conducteur est sous l'empire d'un état alcoolique à partir de 0,3 gramme d'alcool pur par litre de sang. Le taux est de 0 g/l pour les conducteurs stagiaires, les poids lourds, le transport de personnes et les moniteurs.","explication_ar":"منذ الأمر الحكومي عدد 2016-292 المؤرخ في 1 مارس 2016، يُعتبر السائق في حالة سكر ابتداءً من 0,3 غرام من الكحول الصافي في اللتر من الدم. وتكون النسبة 0 غ/ل للسائقين المتربصين وسائقي الوزن الثقيل ونقل الأشخاص والمدربين.","source":"Décret n° 2000-146 du 24 janvier 2000, article 6, modifié par le décret gouvernemental n° 2016-292 du 1er mars 2016","image":"q-taux-alcool.svg"},
{"id":"T7-002","theme":7,"question_fr":"Quelle peine prévoit la loi pour la conduite sous l'empire d'un état alcoolique ?","question_ar":"ما العقوبة التي ينص عليها القانون للسياقة في حالة سكر؟","choix":[{"fr":"Jusqu'à 6 mois de prison et/ou une amende de 200 à 500 DT","ar":"السجن حتى 6 أشهر و/أو خطية من 200 إلى 500 دينار"},{"fr":"Un simple avertissement","ar":"مجرد تنبيه"},{"fr":"Une amende de 20 DT seulement","ar":"خطية بـ 20 دينارًا فقط"}],"bonnes":[0],"explication_fr":"La conduite sous l'empire d'un état alcoolique est un délit puni de six mois d'emprisonnement au maximum et d'une amende de 200 à 500 DT, ou de l'une de ces deux peines. Le permis peut aussi être retiré.","explication_ar":"السياقة في حالة سكر جنحة يُعاقب عليها بالسجن مدة أقصاها ستة أشهر وبخطية من 200 إلى 500 دينار أو بإحدى العقوبتين، ويمكن أيضًا سحب الرخصة.","source":"Code de la route, article 87 (point 1), article 92","image":"q-peine-alcool.svg"},
{"id":"T7-003","theme":7,"question_fr":"Un agent vous demande de souffler dans l'appareil de dépistage et vous refusez. Que risquez-vous ?","question_ar":"عون يطلب منك النفخ في جهاز الكشف عن الكحول وأنت ترفض. بماذا تُخاطر؟","choix":[{"fr":"Les mêmes sanctions que la conduite en état alcoolique (délit, retrait du permis)","ar":"نفس عقوبات السياقة في حالة سكر (جنحة، سحب الرخصة)"},{"fr":"Rien, le dépistage est facultatif","ar":"لا شيء، الكشف اختياري"}],"bonnes":[0],"explication_fr":"Le refus de se soumettre au dépistage ou à la vérification de l'état alcoolique est un délit (même peine que la conduite en état alcoolique) et entraîne le retrait du permis.","explication_ar":"رفض الخضوع للكشف أو للتثبت من حالة السكر جنحة (نفس عقوبة السياقة في حالة سكر) ويؤدي إلى سحب الرخصة.","source":"Code de la route, articles 87 (point 5) et 92 ; Décret n° 2000-146, article 5","image":"q-refus-depistage.svg"},
{"id":"T7-004","theme":7,"question_fr":"Pour une première conduite en état alcoolique, quelle est la durée MAXIMALE du retrait de permis décidé par la commission ?","question_ar":"عند السياقة في حالة سكر لأول مرة، ما المدة القصوى لسحب الرخصة الذي تقرره اللجنة؟","choix":[{"fr":"6 mois","ar":"6 أشهر"},{"fr":"2 ans","ar":"سنتان"},{"fr":"Définitif","ar":"نهائيًا"}],"bonnes":[0],"explication_fr":"Le permis est retiré pour 6 mois au maximum (1 an au maximum en cas de récidive dans l'année qui suit la fin du premier retrait).","explication_ar":"تُسحب الرخصة لمدة أقصاها 6 أشهر (وسنة على الأكثر في حالة العود خلال السنة الموالية لانتهاء السحب الأول).","source":"Code de la route, article 93","image":"q-retrait-alcool.svg"},
{"id":"T7-005","theme":7,"question_fr":"Un agent constate que vous conduisez en état alcoolique. Peut-il retirer votre permis immédiatement ?","question_ar":"عون يعاين أنك تسوق في حالة سكر. هل يمكنه سحب رخصتك فورًا؟","choix":[{"fr":"Oui, la loi permet le retrait immédiat","ar":"نعم، القانون يسمح بالسحب الفوري"},{"fr":"Non, seul un juge peut le faire après plusieurs mois","ar":"لا، فقط القاضي يمكنه ذلك بعد أشهر"}],"bonnes":[0],"explication_fr":"Les agents peuvent procéder au retrait immédiat du permis en cas de conduite en état alcoolique ou de refus du dépistage, d'accident avec mort ou blessures graves, ou de permis suspendu.","explication_ar":"يمكن للأعوان سحب الرخصة فورًا في حالة السياقة في حالة سكر أو رفض الكشف، أو حادث نتج عنه موت أو جروح خطيرة، أو رخصة معلّقة الصلوحية.","source":"Code de la route, article 94 bis (ajouté par la loi 2006-54)","image":"q-agent-retrait.svg"},
{"id":"T7-006","theme":7,"question_fr":"Vous êtes très fatigué (manque de sommeil). Que dit la loi ?","question_ar":"أنت متعب جدًا (قلة نوم). ماذا يقول القانون؟","choix":[{"fr":"Je dois m'abstenir de conduire ; un agent peut immobiliser le véhicule","ar":"يجب أن أمتنع عن السياقة، ويمكن للعون إيقاف العربة"},{"fr":"Je peux conduire si je roule lentement","ar":"يمكنني السياقة إذا سرت ببطء"}],"bonnes":[0],"explication_fr":"Le conducteur doit s'abstenir de conduire s'il est fatigué. Des signes de fatigue évidents (manque de sommeil) entraînent l'immobilisation immédiate du véhicule.","explication_ar":"يجب على السائق الامتناع عن السياقة إذا كان متعبًا. وعلامات التعب الواضحة (قلة النوم) تؤدي إلى الإيقاف الفوري للعربة.","source":"Code de la route, article 7 (point 2) et article 105 (point 2)","image":"q-fatigue.svg"},
{"id":"T7-007","theme":7,"question_fr":"Vous avez pris un médicament tranquillisant qui peut affecter vos réflexes. Pouvez-vous conduire ?","question_ar":"تناولت دواءً مهدئًا قد يؤثر على ردود أفعالك. هل يمكنك السياقة؟","choix":[{"fr":"Non, je dois m'abstenir de conduire","ar":"لا، يجب أن أمتنع عن السياقة"},{"fr":"Oui, ce n'est pas de l'alcool","ar":"نعم، ليس كحولًا"}],"bonnes":[0],"explication_fr":"Tout conducteur doit s'abstenir de conduire s'il a consommé des tranquillisants ou des produits pouvant affecter ses aptitudes.","explication_ar":"يجب على كل سائق الامتناع عن السياقة إذا تناول مهدئات أو مواد قد تؤثر على قدراته.","source":"Code de la route, article 7 (point 2)","image":"q-medicament.svg"},
{"id":"T7-008","theme":7,"question_fr":"L'usage du téléphone portable en conduisant est-il autorisé ?","question_ar":"هل يُسمح باستعمال الهاتف الجوال أثناء السياقة؟","choix":[{"fr":"Non, sauf si la communication se fait sans utiliser les mains (kit mains-libres)","ar":"لا، إلا إذا كانت المكالمة دون استعمال اليدين (جهاز «اليدين الحرّتين»)"},{"fr":"Oui, s'il est tenu d'une seule main","ar":"نعم، إذا كان ممسوكًا بيد واحدة"},{"fr":"Oui, en agglomération","ar":"نعم، داخل المناطق العمرانية"}],"bonnes":[0],"explication_fr":"Il est interdit d'utiliser le téléphone mobile en conduisant, sauf si la communication est possible sans utiliser les deux mains ou l'une d'elles (et sauf véhicules des forces de sécurité et de l'armée).","explication_ar":"يُمنع استعمال الهاتف الجوال أثناء السياقة، إلا إذا كانت المكالمة ممكنة دون استعمال اليدين أو إحداهما (وباستثناء عربات قوات الأمن والجيش).","source":"Décret n° 2000-151, article 2 (alinéa ajouté par le décret 2001-2281)","image":"q-telephone.svg"},
{"id":"T7-009","theme":7,"question_fr":"Quelle amende est prévue pour l'usage du téléphone tenu en main en conduisant ?","question_ar":"ما الخطية المقررة لاستعمال الهاتف باليد أثناء السياقة؟","choix":[{"fr":"20 DT","ar":"20 دينارًا"},{"fr":"40 DT","ar":"40 دينارًا"},{"fr":"60 DT","ar":"60 دينارًا"}],"bonnes":[2],"explication_fr":"L'usage du téléphone en conduisant est classé dans la catégorie de contraventions la plus grave, dont l'amende est de 60 DT depuis la loi de finances 2025. Le kit mains libres reste autorisé.","explication_ar":"يُصنَّف استعمال الهاتف أثناء السياقة في أخطر صنف من المخالفات، وخطيته 60 دينارًا منذ قانون المالية لسنة 2025. تبقى السماعات التي لا تتطلب استعمال اليدين مسموحًا بها.","source":"Décret n° 2010-262 du 15 février 2010, tableau, n° 16 ; loi n° 2024-48 du 9 décembre 2024 (loi de finances 2025), article 49","image":"q-amende-telephone.svg"},
{"id":"T7-010","theme":7,"question_fr":"Un conducteur de camion de plus de 12 t a conduit 4 h 30 sans arrêt. Que doit-il faire ?","question_ar":"سائق شاحنة يفوق وزنها 12 طنًا ساق 4 ساعات و30 دقيقة دون توقف. ماذا يجب أن يفعل؟","choix":[{"fr":"Prendre un repos d'au moins 45 minutes","ar":"أخذ راحة لا تقل عن 45 دقيقة"},{"fr":"Continuer jusqu'à 9 h de conduite","ar":"المواصلة حتى 9 ساعات سياقة"},{"fr":"Prendre 5 minutes de pause","ar":"أخذ استراحة 5 دقائق"}],"bonnes":[0],"explication_fr":"Après 4 h 30 de conduite continue, repos d'au moins 45 minutes (peut être fractionné en pauses d'au moins 15 minutes). La conduite effective est limitée à 9 h par jour.","explication_ar":"بعد 4 ساعات و30 دقيقة من السياقة المتواصلة يجب أخذ راحة لا تقل عن 45 دقيقة (يمكن تقسيمها إلى فترات لا تقل كل منها عن 15 دقيقة). والسياقة الفعلية محددة بـ 9 ساعات في اليوم.","source":"Décret n° 2000-145, articles 1 à 4","image":"q-camion-pause.svg"},
{"id":"T7-011","theme":7,"question_fr":"Combien de points perd-on pour une conduite en état alcoolique établie par un jugement définitif ?","question_ar":"كم نقطة يخسر السائق بسبب السياقة في حالة سكر الثابتة بحكم نهائي؟","choix":[{"fr":"2 points","ar":"نقطتان"},{"fr":"4 points","ar":"4 نقاط"},{"fr":"10 points","ar":"10 نقاط"}],"bonnes":[1],"explication_fr":"La conduite sous l'empire d'un état alcoolique dûment établie entraîne un retrait de 4 points, après jugement définitif.","explication_ar":"السياقة في حالة سكر الثابتة تؤدي إلى سحب 4 نقاط بعد صدور حكم نهائي.","source":"Décret n° 2000-144, article 3 (point 3) et article 5","image":"q-points-alcool.svg"},
{"id":"T7-012","theme":7,"question_fr":"Un conducteur ivre cause un accident mortel. Quelle peine maximale de prison est prévue ?","question_ar":"سائق في حالة سكر يتسبب في حادث قاتل. ما أقصى عقوبة سجن منصوص عليها؟","choix":[{"fr":"1 an et 1 mois","ar":"سنة وشهر"},{"fr":"5 ans","ar":"5 سنوات"},{"fr":"6 mois","ar":"6 أشهر"}],"bonnes":[1],"explication_fr":"L'homicide involontaire est puni de 5 ans de prison et 5 000 DT d'amende si le conducteur était en état alcoolique (ou sans permis, ou sans assurance) ; jusqu'à 10 ans en cas de fuite.","explication_ar":"يُعاقب على القتل على وجه الخطأ بالسجن 5 سنوات وبخطية 5000 دينار إذا كان السائق في حالة سكر (أو بدون رخصة أو بدون تأمين)، وتصل العقوبة إلى 10 سنوات في حالة الفرار.","source":"Code de la route, articles 90 et 91","image":"q-accident-alcool.svg"},
{"id":"T7-013","theme":7,"question_fr":"Vous êtes conducteur stagiaire (nouveau permis, période de stage). Quel taux d'alcool dans le sang vous est autorisé ?","question_ar":"أنت سائق متربص (رخصة جديدة، فترة التربص). ما نسبة الكحول في الدم المسموح بها لك؟","choix":[{"fr":"0 g/l : aucune trace d'alcool","ar":"0 غ/ل: لا أثر للكحول"},{"fr":"0,3 g/l","ar":"0,3 غ/ل"},{"fr":"0,5 g/l","ar":"0,5 غ/ل"}],"bonnes":[0],"explication_fr":"Pour les conducteurs stagiaires, le taux autorisé est réduit à 0 gramme par litre (décret gouvernemental n° 2016-292). Même chose pour les poids lourds, le transport de personnes, le transport touristique et les moniteurs.","explication_ar":"بالنسبة إلى السائقين المتربصين، النسبة المسموح بها مخفّضة إلى 0 غرام في اللتر (الأمر الحكومي عدد 2016-292). والأمر نفسه لسائقي الوزن الثقيل ونقل الأشخاص والنقل السياحي والمدربين.","source":"Décret n° 2000-146, article 6, modifié par le décret gouvernemental n° 2016-292 du 1er mars 2016","image":"q-alcool-stagiaire.svg"},
{"id":"T8-001","theme":8,"question_fr":"Les témoins d'usure des pneus d'une voiture signalent que les rainures ne font plus que :","question_ar":"مؤشرات تآكل عجلات السيارة تنبّه إلى أن عمق الأخاديد لم يعد يتجاوز:","choix":[{"fr":"1,6 mm","ar":"1,6 مم"},{"fr":"3 mm","ar":"3 مم"},{"fr":"5 mm","ar":"5 مم"}],"bonnes":[0],"explication_fr":"Les pneus des voitures particulières, mixtes et camionnettes ont un indicateur d'usure (bossages dans les rainures) qui signale une profondeur de 1,6 mm.","explication_ar":"عجلات السيارات الخاصة والمختلطة والشاحنات الخفيفة مجهزة بمؤشر تآكل (نتوءات داخل الأخاديد) ينبّه عندما يصبح العمق 1,6 مم.","source":"Décret n° 2000-147, article 11","image":"q-temoin-usure.svg"},
{"id":"T8-002","theme":8,"question_fr":"En mesurant la profondeur des rainures d'un pneu en 4 points, combien de points peuvent être en dessous de 1 mm au maximum ?","question_ar":"عند قياس عمق أخاديد العجلة في 4 نقاط، كم نقطة على الأكثر يمكن أن يكون عمقها أقل من 1 مم؟","choix":[{"fr":"Aucun","ar":"ولا نقطة"},{"fr":"Un seul","ar":"نقطة واحدة"},{"fr":"Deux","ar":"نقطتان"}],"bonnes":[1],"explication_fr":"Il ne doit pas exister plus d'un point (sur quatre) où la profondeur mesurée est inférieure à 1 mm. Rouler avec des pneus non conformes est une contravention.","explication_ar":"يجب ألا توجد أكثر من نقطة واحدة (من أربع) يكون فيها العمق أقل من 1 مم. والسياقة بعجلات غير مطابقة مخالفة.","source":"Décret n° 2000-147, articles 16 et 17 ; Décret n° 2010-262, n° 111","image":"q-mesure-pneu.svg"},
{"id":"T8-003","theme":8,"question_fr":"Peut-on monter deux pneus de dimensions différentes sur le même essieu ?","question_ar":"هل يمكن تركيب عجلتين بمقاسين مختلفين على نفس المحور؟","choix":[{"fr":"Non, c'est interdit","ar":"لا، هذا ممنوع"},{"fr":"Oui, sans problème","ar":"نعم، دون مشكل"}],"bonnes":[0],"explication_fr":"Il est interdit de monter sur le même essieu des pneus de dimensions différentes, ou de structures différentes (radial / diagonal).","explication_ar":"يُمنع تركيب عجلات بمقاسات مختلفة أو بهياكل مختلفة (شعاعية / قطرية) على نفس المحور.","source":"Décret n° 2000-147, article 14","image":"q-pneus-dimensions.svg"},
{"id":"T8-004","theme":8,"question_fr":"Sur un même essieu d'une voiture, quelle différence maximale de profondeur des rainures est admise entre les deux pneus ?","question_ar":"على نفس محور السيارة، ما أقصى فارق مسموح به في عمق الأخاديد بين العجلتين؟","choix":[{"fr":"1 mm","ar":"1 مم"},{"fr":"5 mm","ar":"5 مم"},{"fr":"Aucune limite","ar":"لا حدّ"}],"bonnes":[1],"explication_fr":"Pour les voitures particulières, mixtes et camionnettes, la différence de profondeur des rainures principales entre deux pneus d'un même essieu ne doit pas dépasser 5 mm.","explication_ar":"بالنسبة للسيارات الخاصة والمختلطة والشاحنات الخفيفة، يجب ألا يتجاوز الفارق في عمق الأخاديد الرئيسية بين عجلتي نفس المحور 5 مم.","source":"Décret n° 2000-147, article 16 (alinéa 2)","image":"q-pneus-essieu.svg"},
{"id":"T8-005","theme":8,"question_fr":"Quels éléments une voiture doit-elle obligatoirement avoir pour changer une roue ?","question_ar":"ما العناصر التي يجب أن تكون وجوبًا في السيارة لتغيير عجلة؟","choix":[{"fr":"Une roue de secours en bon état et les outils de montage/démontage","ar":"عجلة احتياطية في حالة جيدة وأدوات التركيب والفك"},{"fr":"Rien, ce n'est pas obligatoire","ar":"لا شيء، ليس وجوبيًا"}],"bonnes":[0],"explication_fr":"Les automobiles doivent être munies d'une roue de secours en bon état et des outils nécessaires au montage et au démontage des roues.","explication_ar":"يجب أن تكون السيارات مجهزة بعجلة احتياطية في حالة جيدة وبالأدوات اللازمة لتركيب العجلات وفكّها.","source":"Décret n° 2000-147, article 8","image":"q-changer-roue.svg"},
{"id":"T8-006","theme":8,"question_fr":"Combien de dispositifs de freinage indépendants une automobile doit-elle avoir ?","question_ar":"كم جهاز فرملة مستقل يجب أن تكون للسيارة؟","choix":[{"fr":"Un seul","ar":"جهاز واحد"},{"fr":"Deux : un principal et un secondaire (frein de stationnement)","ar":"جهازان: رئيسي وثانوي (فرامل الوقوف)"},{"fr":"Trois","ar":"ثلاثة"}],"bonnes":[1],"explication_fr":"Toute automobile doit avoir deux dispositifs de freinage à commandes indépendantes : le principal (arrêter le véhicule) et le secondaire (maintenir le véhicule à l'arrêt).","explication_ar":"يجب أن تكون لكل سيارة جهازا فرملة بقيادتين مستقلتين: الرئيسي (لإيقاف العربة) والثانوي (لإبقائها متوقفة).","source":"Décret n° 2000-147, article 51","image":"q-freinage.svg"},
{"id":"T8-007","theme":8,"question_fr":"Quels rétroviseurs une voiture particulière doit-elle avoir au minimum ?","question_ar":"ما المرايا العاكسة الدنيا التي يجب أن تكون في السيارة الخاصة؟","choix":[{"fr":"Un rétroviseur intérieur et un rétroviseur extérieur gauche","ar":"مرآة داخلية ومرآة خارجية على اليسار"},{"fr":"Seulement un rétroviseur intérieur","ar":"مرآة داخلية فقط"},{"fr":"Aucun rétroviseur n'est obligatoire","ar":"لا توجد مرآة وجوبية"}],"bonnes":[0],"explication_fr":"Les voitures particulières doivent avoir un rétroviseur intérieur et un rétroviseur extérieur à gauche (un droit en plus dans certains cas : break, remorque masquant la vue…).","explication_ar":"يجب أن تكون للسيارات الخاصة مرآة داخلية ومرآة خارجية على اليسار (وتُضاف مرآة يمنى في بعض الحالات: سيارة «بريك»، مجرورة تحجب الرؤية...).","source":"Décret n° 2000-147, articles 40 et 41","image":"q-retroviseurs.svg"},
{"id":"T8-008","theme":8,"question_fr":"Le pare-brise d'une voiture doit être équipé :","question_ar":"يجب أن يكون البلّور الأمامي للسيارة مجهزًا بـ:","choix":[{"fr":"D'au moins un essuie-glace et d'un lave-glace","ar":"ماسحة زجاج واحدة على الأقل وجهاز غسل الزجاج"},{"fr":"D'un film teinté","ar":"غشاء ملوّن"},{"fr":"De rien de particulier","ar":"لا شيء خاص"}],"bonnes":[0],"explication_fr":"Le pare-brise doit être muni d'au moins un essuie-glace efficace et d'un dispositif de lave-glace.","explication_ar":"يجب أن يكون البلّور الأمامي مجهزًا بماسحة زجاج فعالة واحدة على الأقل وبجهاز لغسل الزجاج.","source":"Décret n° 2000-147, article 34","image":"q-pare-brise.svg"},
{"id":"T8-009","theme":8,"question_fr":"Peut-on retirer ou percer le silencieux de l'échappement pour faire plus de bruit ?","question_ar":"هل يمكن نزع كاتم صوت العادم أو ثقبه لإحداث ضجيج أكثر؟","choix":[{"fr":"Non, l'échappement libre est interdit","ar":"لا، العادم الحر ممنوع"},{"fr":"Oui, si le moteur est puissant","ar":"نعم، إذا كان المحرك قويًا"}],"bonnes":[0],"explication_fr":"Le moteur doit avoir un silencieux en bon état ; l'échappement libre et toute opération réduisant l'efficacité du silencieux sont interdits.","explication_ar":"يجب أن يكون للمحرك كاتم صوت في حالة جيدة، ويُمنع العادم الحر وكل عملية تُنقص من فعالية كاتم الصوت.","source":"Décret n° 2000-147, article 27","image":"q-silencieux.svg"},
{"id":"T8-010","theme":8,"question_fr":"Qui paie la visite technique périodique d'un véhicule ?","question_ar":"من يدفع معلوم الفحص الفني الدوري للعربة؟","choix":[{"fr":"Le propriétaire du véhicule","ar":"مالك العربة"},{"fr":"L'État","ar":"الدولة"},{"fr":"L'assurance","ar":"شركة التأمين"}],"bonnes":[0],"explication_fr":"Les véhicules doivent passer périodiquement une visite technique ; les frais sont à la charge des propriétaires. La visite ne dispense pas d'entretenir le véhicule.","explication_ar":"يجب أن تخضع العربات دوريًا لفحص فني، ومعاليمه على حساب مالكيها. ولا يعفي الفحص من واجب صيانة العربة.","source":"Code de la route, articles 64 et 65","image":"q-visite-technique.svg"},
{"id":"T8-011","theme":8,"question_fr":"Quels documents devez-vous présenter lors d'un contrôle routier ? (plusieurs réponses)","question_ar":"ما الوثائق التي يجب تقديمها عند المراقبة المرورية؟ (عدة إجابات)","choix":[{"fr":"Le permis de conduire","ar":"رخصة السياقة"},{"fr":"Le certificat d'immatriculation (carte grise)","ar":"شهادة التسجيل (البطاقة الرمادية)"},{"fr":"L'attestation d'assurance","ar":"شهادة التأمين"},{"fr":"La justification de la visite technique","ar":"ما يثبت الفحص الفني"}],"bonnes":[0,1,2,3],"explication_fr":"Pièces exigées : permis correspondant au véhicule, certificat d'immatriculation, attestation d'assurance, justification de la visite technique, justification du paiement des taxes de circulation (vignette).","explication_ar":"الوثائق المطلوبة: رخصة السياقة الموافقة لنوع العربة، شهادة التسجيل، شهادة التأمين، ما يثبت الفحص الفني، وما يثبت دفع معاليم الجولان.","source":"Décret n° 2000-152, article 1 ; Code de la route, article 99","image":"q-documents-controle.svg"},
{"id":"T8-012","theme":8,"question_fr":"Où la ceinture de sécurité est-elle obligatoire pour le conducteur et le passager avant ?","question_ar":"أين يكون حزام الأمان وجوبيًا للسائق وللراكب الأمامي؟","choix":[{"fr":"Partout : en agglomération, hors agglomération et sur autoroute","ar":"في كل مكان: داخل المناطق العمرانية وخارجها وعلى الطرق السيارة"},{"fr":"Seulement sur les autoroutes et en dehors des villes","ar":"فقط على الطرق السيارة وخارج المدن"},{"fr":"Nulle part, elle est seulement conseillée","ar":"في أي مكان، هو مجرد نصيحة"}],"bonnes":[0],"explication_fr":"Depuis le 27 avril 2017, la ceinture est obligatoire à l'intérieur et à l'extérieur des agglomérations et sur les autoroutes pour le conducteur et le passager avant. Depuis le 27 janvier 2018, elle l'est aussi pour les passagers arrière.","explication_ar":"منذ 27 أفريل 2017، أصبح حزام الأمان وجوبيًا داخل المناطق العمرانية وخارجها وعلى الطرق السيارة للسائق وللراكب الأمامي. ومنذ 27 جانفي 2018، أصبح وجوبيًا أيضًا للركاب الخلفيين.","source":"Décret n° 2000-147, article 82, modifié par le décret du 6 janvier 2017 (JORT n° 8 du 27 janvier 2017)","image":"q-ceinture.svg"},
{"id":"T8-013","theme":8,"question_fr":"Le conducteur et le passager d'une moto doivent-ils porter un casque ?","question_ar":"هل يجب على سائق الدراجة النارية ومرافقه ارتداء الخوذة؟","choix":[{"fr":"Oui, tous les deux, en agglomération et hors agglomération","ar":"نعم، كلاهما، داخل المناطق العمرانية وخارجها"},{"fr":"Seulement le conducteur","ar":"السائق فقط"},{"fr":"Seulement sur autoroute","ar":"على الطريق السيارة فقط"}],"bonnes":[0],"explication_fr":"Le conducteur d'un motocycle à deux roues et son passager doivent porter un casque conforme, en agglomération comme hors agglomération.","explication_ar":"يجب على سائق الدراجة النارية ذات العجلتين ومرافقه ارتداء خوذة مطابقة للمواصفات، داخل المناطق العمرانية وخارجها.","source":"Code de la route, article 73 ; Arrêté du ministre du Transport du 25 janvier 2000 (cycles et cyclomoteurs), chapitre II","image":"q-casque-moto.svg"},
{"id":"T9-001","theme":9,"question_fr":"Vous êtes impliqué dans un accident de la circulation. Quelle est votre première obligation ?","question_ar":"أنت طرف في حادث مرور. ما هو أول واجب عليك؟","choix":[{"fr":"M'arrêter immédiatement en prenant les précautions pour éviter un autre danger","ar":"التوقف فورًا مع اتخاذ الاحتياطات لتفادي خطر إضافي"},{"fr":"Partir rapidement pour ne pas gêner","ar":"المغادرة بسرعة حتى لا أعرقل الحركة"},{"fr":"Déplacer tous les véhicules avant tout","ar":"تحريك كل العربات قبل كل شيء"}],"bonnes":[0],"explication_fr":"Tout conducteur impliqué dans un accident doit s'arrêter immédiatement en prenant les précautions nécessaires pour éviter un danger supplémentaire ou une gêne à la circulation.","explication_ar":"يجب على كل سائق طرف في حادث مرور أن يتوقف فورًا مع اتخاذ الاحتياطات اللازمة لتفادي أي خطر إضافي أو عرقلة للحركة.","source":"Code de la route, article 60","image":"q-accident-premiere.svg"},
{"id":"T9-002","theme":9,"question_fr":"Un accident a fait un blessé. Que devez-vous faire ? (plusieurs réponses)","question_ar":"حادث نتج عنه جريح. ماذا يجب أن تفعل؟ (عدة إجابات)","choix":[{"fr":"Avertir ou faire avertir immédiatement la Police ou la Garde nationale","ar":"إعلام الشرطة أو الحرس الوطني فورًا أو العمل على إعلامهم"},{"fr":"Éviter de modifier l'état des lieux et les traces","ar":"تجنب تغيير حالة المكان والآثار"},{"fr":"Effacer les traces de freinage","ar":"محو آثار الفرملة"}],"bonnes":[0,1],"explication_fr":"Si l'accident a causé la mort ou des blessures, il faut avertir immédiatement la Police ou la Garde nationale et éviter de modifier les lieux ou faire disparaître les traces, sans gêner la circulation.","explication_ar":"إذا نتج عن الحادث موت أو جروح، يجب إعلام الشرطة أو الحرس الوطني فورًا وتجنب تغيير حالة المكان أو إزالة الآثار، دون عرقلة الحركة.","source":"Code de la route, article 60","image":"q-accident-blesse.svg"},
{"id":"T9-003","theme":9,"question_fr":"Accident entre deux particuliers avec seulement des dégâts matériels. Que faites-vous ?","question_ar":"حادث بين خواص نتجت عنه أضرار مادية فقط. ماذا تفعل؟","choix":[{"fr":"Nous remplissons et signons un constat à l'amiable, puis j'informe mon assurance dans les délais","ar":"نعمّر ونمضي محضر معاينة بالتراضي، ثم أُعلم شركة التأمين في الآجال"},{"fr":"Je pars sans rien dire","ar":"أغادر دون قول أي شيء"}],"bonnes":[0],"explication_fr":"Pour les accidents entre particuliers, on établit et signe un constat à l'amiable et on informe la société d'assurance dans les délais réglementaires.","explication_ar":"في الحوادث بين الخواص يتم تحرير وإمضاء محضر معاينة بالتراضي (constat) وإعلام شركة التأمين في الآجال القانونية.","source":"Code de la route, article 60","image":"q-accident-materiel.svg"},
{"id":"T9-004","theme":9,"question_fr":"En manœuvrant, vous abîmez une voiture garée dont le conducteur est absent. Que devez-vous faire ?","question_ar":"أثناء مناورة، أتلفت سيارة واقفة وسائقها غائب. ماذا يجب أن تفعل؟","choix":[{"fr":"Informer immédiatement la Police ou la Garde nationale","ar":"إعلام الشرطة أو الحرس الوطني فورًا"},{"fr":"Partir, personne ne m'a vu","ar":"المغادرة، لم يرني أحد"}],"bonnes":[0],"explication_fr":"Il faut informer immédiatement la Police ou la Garde nationale quand l'accident a causé des dégâts matériels à un véhicule stationné en l'absence de son conducteur. Fuir après des dégâts matériels est un délit.","explication_ar":"يجب إعلام الشرطة أو الحرس الوطني فورًا عندما يتسبب الحادث في أضرار مادية لعربة واقفة في غياب سائقها. والفرار بعد التسبب في أضرار مادية جنحة.","source":"Code de la route, articles 60 et 86 (point 5)","image":"q-voiture-garee-abimee.svg"},
{"id":"T9-005","theme":9,"question_fr":"Votre voiture est en panne sur la chaussée d'une route ordinaire et constitue un danger. À quelle distance minimale placez-vous le triangle de danger ?","question_ar":"سيارتك معطلة على معبّد طريق عادية وتشكّل خطرًا. على أي مسافة دنيا تضع مثلث الخطر؟","choix":[{"fr":"10 m","ar":"10 م"},{"fr":"30 m","ar":"30 م"},{"fr":"100 m","ar":"100 م"}],"bonnes":[1],"explication_fr":"Le triangle est placé à au moins 30 m sur les routes et 100 m sur les autoroutes, visible à 50 m au moins de jour comme de nuit. En agglomération, il peut être plus proche si 30 m est impossible.","explication_ar":"يوضع المثلث على بعد 30 م على الأقل في الطرق و100 م على الطرق السيارة، بحيث يُرى من مسافة 50 م على الأقل نهارًا وليلًا. وداخل المناطق العمرانية يمكن وضعه أقرب إذا تعذّر احترام 30 م.","source":"Décret n° 2000-151, articles 42 et 43","image":"q-triangle-route.svg"},
{"id":"T9-006","theme":9,"question_fr":"Sur autoroute, à quelle distance minimale placez-vous le triangle de danger derrière un véhicule en panne ?","question_ar":"على الطريق السيارة، على أي مسافة دنيا تضع مثلث الخطر خلف عربة معطّبة؟","choix":[{"fr":"30 m","ar":"30 م"},{"fr":"50 m","ar":"50 م"},{"fr":"100 m","ar":"100 م"}],"bonnes":[2],"explication_fr":"Sur autoroute, le triangle est placé à au moins 100 m. On peut aussi allumer les feux de détresse ou un feu portatif jaune clignotant.","explication_ar":"على الطريق السيارة يوضع المثلث على بعد 100 م على الأقل، ويمكن أيضًا تشغيل أضواء الخطر أو ضوء محمول أصفر وامض.","source":"Décret n° 2000-151, article 43","image":"q-triangle-autoroute.svg"},
{"id":"T9-007","theme":9,"question_fr":"Sur autoroute, votre véhicule tombe en panne. Que devez-vous faire en priorité ?","question_ar":"على الطريق السيارة تعطّلت عربتك. ماذا يجب أن تفعل أولًا؟","choix":[{"fr":"Dégager si possible le véhicule de la chaussée et de la bande d'arrêt d'urgence ; sinon le signaler pour qu'on le voie de loin","ar":"إخراج العربة إن أمكن من المعبّد ومن شريط التوقف الاستعجالي، وإلا الإشارة إليها حتى تُرى من بعيد"},{"fr":"Faire marche arrière jusqu'à la dernière sortie","ar":"الرجوع إلى الخلف حتى آخر مخرج"},{"fr":"Traverser le terre-plein central à pied","ar":"عبور الفاصل الأوسط مشيًا"}],"bonnes":[0],"explication_fr":"En cas d'arrêt inévitable, le conducteur doit s'efforcer de dégager le véhicule de la chaussée et de la bande d'arrêt d'urgence, sinon le signaler pour que les autres le voient à distance suffisante. La marche arrière est interdite sur autoroute.","explication_ar":"عند التوقف الاضطراري يجب على السائق أن يسعى لإخراج العربة من المعبّد ومن شريط التوقف الاستعجالي، وإلا الإشارة إليها حتى يراها الآخرون من مسافة كافية. والرجوع إلى الخلف ممنوع على الطريق السيارة.","source":"Décret n° 2000-151, article 48","image":"q-panne-autoroute.svg"},
{"id":"T9-008","theme":9,"question_fr":"Après un accident, dans quel délai le propriétaire doit-il enlever son véhicule endommagé resté sur la route ?","question_ar":"بعد حادث، في أي أجل يجب على المالك إزالة عربته المتضررة التي بقيت على الطريق؟","choix":[{"fr":"24 heures","ar":"24 ساعة"},{"fr":"7 jours","ar":"7 أيام"},{"fr":"30 jours","ar":"30 يومًا"}],"bonnes":[1],"explication_fr":"Le véhicule en panne suite à un accident doit être enlevé par son propriétaire dans les 7 jours ; ensuite il est mis en fourrière à ses frais.","explication_ar":"يجب على المالك إزالة العربة المعطّبة إثر حادث في أجل 7 أيام، وبعد ذلك توضع في المستودع البلدي على نفقته.","source":"Décret n° 2000-151, article 63","image":"q-enlever-vehicule.svg"},
{"id":"T9-009","theme":9,"question_fr":"Un conducteur cause un accident avec blessé et prend la fuite volontairement. Quelle peine de prison maximale encourt-il ?","question_ar":"سائق تسبب في حادث نتج عنه جريح ثم فرّ عمدًا. ما أقصى عقوبة سجن يتعرض لها؟","choix":[{"fr":"6 mois","ar":"6 أشهر"},{"fr":"2 ans","ar":"سنتان"},{"fr":"10 ans","ar":"10 سنوات"}],"bonnes":[2],"explication_fr":"La peine de prison est portée à 10 ans s'il est prouvé que le conducteur a sciemment pris la fuite. Il perd aussi 6 points (blessure) ou 10 points (homicide).","explication_ar":"ترتفع عقوبة السجن إلى 10 سنوات إذا ثبت أن السائق فرّ عن قصد. ويخسر كذلك 6 نقاط (جروح) أو 10 نقاط (قتل).","source":"Code de la route, article 91 ; Décret n° 2000-144, article 3","image":"q-delit-fuite.svg"},
{"id":"T9-012","theme":9,"question_fr":"Quel numéro appeler en Tunisie pour le SAMU (urgence médicale) ?","question_ar":"ما الرقم الذي يُطلب في تونس للإسعاف الطبي الاستعجالي (SAMU)؟","choix":[{"fr":"190","ar":"190"},{"fr":"198","ar":"198"},{"fr":"197","ar":"197"}],"bonnes":[0],"explication_fr":"Numéros usuels en Tunisie : SAMU 190, Protection civile 198, Police 197, Garde nationale 193.","explication_ar":"الأرقام المعتادة في تونس: الإسعاف الطبي الاستعجالي 190، الحماية المدنية 198، الشرطة 197، الحرس الوطني 193.","source":"Ministère de la Santé : numéro d'urgence 190 (SAMU)","image":"q-numero-samu.svg"},
{"id":"T10-001","theme":10,"question_fr":"Combien de points compte le capital d'un permis de conduire ?","question_ar":"كم نقطة يحتوي رصيد رخصة السياقة؟","choix":[{"fr":"12 points","ar":"12 نقطة"},{"fr":"20 points","ar":"20 نقطة"},{"fr":"25 points","ar":"25 نقطة"}],"bonnes":[2],"explication_fr":"Chaque permis de conduire dispose d'un capital de 25 points.","explication_ar":"يُسند لكل رخصة سياقة رصيد بـ 25 نقطة.","source":"Code de la route, article 78 ; Décret n° 2000-144, article 2","image":"q-capital-points.svg"},
{"id":"T10-002","theme":10,"question_fr":"Combien de points perd-on pour un excès de vitesse de 40 km/h ou plus ?","question_ar":"كم نقطة يخسر السائق عند تجاوز السرعة القصوى بـ 40 كم/س أو أكثر؟","choix":[{"fr":"2 points","ar":"نقطتان"},{"fr":"4 points","ar":"4 نقاط"},{"fr":"6 points","ar":"6 نقاط"}],"bonnes":[1],"explication_fr":"Retrait de 4 points pour : excès de vitesse de 40 km/h ou plus, conduite sans la catégorie requise, conduite en état alcoolique, sens interdit ou demi-tour sur autoroute (après jugement définitif).","explication_ar":"تُسحب 4 نقاط في حالات: تجاوز السرعة القصوى بـ 40 كم/س أو أكثر، السياقة دون الصنف المطلوب، السياقة في حالة سكر، السير في الاتجاه المعاكس أو الدوران على الطريق السيارة (بعد حكم نهائي).","source":"Décret n° 2000-144, article 3 (point 3)","image":"q-points-vitesse.svg"},
{"id":"T10-003","theme":10,"question_fr":"Comment récupère-t-on automatiquement ses points perdus ?","question_ar":"كيف تُسترجع النقاط المسحوبة بصفة آلية؟","choix":[{"fr":"En ne commettant aucune nouvelle infraction entraînant un retrait de points pendant 2 ans","ar":"بعدم ارتكاب أي مخالفة جديدة تؤدي إلى سحب نقاط لمدة سنتين"},{"fr":"En payant une somme d'argent","ar":"بدفع مبلغ مالي"},{"fr":"Ils ne reviennent jamais","ar":"لا تُسترجع أبدًا"}],"bonnes":[0],"explication_fr":"Les points retirés sont réintégrés si le titulaire ne commet pas de nouvelle infraction entraînant un retrait de points pendant 2 ans après le jugement définitif ou le paiement de l'amende.","explication_ar":"تُرجع النقاط المسحوبة إذا لم يرتكب صاحب الرخصة مخالفة جديدة تستوجب سحب نقاط خلال سنتين من تاريخ الحكم النهائي أو دفع الخطية.","source":"Décret n° 2000-144, article 11","image":"q-recuperer-points.svg"},
{"id":"T10-004","theme":10,"question_fr":"Un stage de sensibilisation de 3 jours permet de récupérer combien de points ?","question_ar":"دورة تحسيسية مدتها 3 أيام تسمح باسترجاع كم نقطة؟","choix":[{"fr":"2 points","ar":"نقطتان"},{"fr":"4 points","ar":"4 نقاط"},{"fr":"Tous les points","ar":"كل النقاط"}],"bonnes":[1],"explication_fr":"Le stage de 3 jours rend 4 points ; il est réservé à ceux qui ont perdu au moins 5 points, et ne peut être utilisé qu'une fois tous les 2 ans. Les frais sont à la charge du participant.","explication_ar":"الدورة التكوينية لمدة 3 أيام ترجع 4 نقاط، وهي مخصصة لمن خسر 5 نقاط على الأقل، ولا يمكن الانتفاع بها إلا مرة واحدة كل سنتين، ومصاريفها على حساب المشارك.","source":"Décret n° 2000-144, articles 12, 17 et 19","image":"q-stage-points.svg"},
{"id":"T10-005","theme":10,"question_fr":"Tous vos points sont perdus. Après combien de temps minimum pouvez-vous demander un nouveau permis ?","question_ar":"خسرت كل نقاطك. بعد كم من الوقت على الأقل يمكنك طلب رخصة جديدة؟","choix":[{"fr":"1 mois","ar":"شهر"},{"fr":"3 mois","ar":"3 أشهر"},{"fr":"5 ans","ar":"5 سنوات"}],"bonnes":[1],"explication_fr":"Quand le capital est épuisé, le permis perd sa validité ; on ne peut demander un nouveau permis qu'après 3 mois à compter de sa remise, et après avoir réussi les examens.","explication_ar":"عند نفاد الرصيد تفقد الرخصة صلوحيتها، ولا يمكن طلب رخصة جديدة إلا بعد 3 أشهر من تاريخ تسليمها وبعد النجاح في الامتحانات.","source":"Code de la route, article 78 ; Décret n° 2000-144, articles 21 et 24","image":"q-points-perdus.svg"},
{"id":"T10-006","theme":10,"question_fr":"Vous ne payez pas une amende de contravention dans les 15 jours après l'infraction. Que se passe-t-il ?","question_ar":"لم تدفع خطية مخالفة في أجل 15 يومًا من تاريخ المخالفة. ماذا يحدث؟","choix":[{"fr":"Le montant de l'amende est doublé","ar":"يُضاعف مبلغ الخطية"},{"fr":"L'amende est annulée","ar":"تُلغى الخطية"},{"fr":"Rien","ar":"لا شيء"}],"bonnes":[0],"explication_fr":"L'amende est doublée si elle n'est pas réglée dans les 15 jours ; après 1 mois sans paiement, le permis est considéré comme suspendu jusqu'au paiement.","explication_ar":"تُضاعف الخطية إذا لم تُدفع في أجل 15 يومًا، وبعد شهر دون دفع تُعتبر الرخصة معلّقة الصلوحية إلى حين الدفع.","source":"Code de la route, article 114 (modifié par la loi 2006-54)","image":"q-amende-15-jours.svg"},
{"id":"T10-007","theme":10,"question_fr":"Une amende de contravention reste impayée plus d'un mois après l'infraction. Quelle conséquence pour le permis ?","question_ar":"خطية مخالفة بقيت دون دفع أكثر من شهر بعد المخالفة. ما النتيجة بالنسبة للرخصة؟","choix":[{"fr":"Le permis est considéré comme suspendu jusqu'au paiement","ar":"تُعتبر الرخصة معلّقة الصلوحية إلى حين الدفع"},{"fr":"Aucune conséquence","ar":"لا نتيجة"}],"bonnes":[0],"explication_fr":"Après un mois sans paiement, le receveur des finances informe le fichier national des infractions et le permis est considéré comme suspendu et non valable jusqu'au paiement ou la régularisation.","explication_ar":"بعد شهر دون دفع يُعلم القابض المالي السجل الوطني للمخالفات، وتُعتبر الرخصة معلّقة الصلوحية وغير صالحة للسياقة إلى حين الدفع أو التسوية.","source":"Code de la route, article 114","image":"q-amende-un-mois.svg"},
{"id":"T10-008","theme":10,"question_fr":"Quelle amende prévoit la loi pour un excès de vitesse de 50 km/h ou plus ?","question_ar":"ما الخطية التي ينص عليها القانون لتجاوز السرعة القصوى بـ 50 كم/س أو أكثر؟","choix":[{"fr":"De 120 à 240 DT (c'est un délit)","ar":"من 120 إلى 240 دينارًا (جنحة)"},{"fr":"20 DT","ar":"20 دينارًا"},{"fr":"Aucune amende","ar":"لا خطية"}],"bonnes":[0],"explication_fr":"Dépasser la vitesse maximale de 50 km/h ou plus est un délit puni d'une amende de 120 à 240 DT ; le procès-verbal est transmis à la justice.","explication_ar":"تجاوز السرعة القصوى بـ 50 كم/س أو أكثر جنحة يُعاقب عليها بخطية من 120 إلى 240 دينارًا، ويُحال المحضر على القضاء.","source":"Code de la route, articles 86 (alinéa 2) et 101 bis","image":"q-amende-vitesse.svg"},
{"id":"T10-009","theme":10,"question_fr":"Quelle est la sanction prévue pour un dépassement interdit ?","question_ar":"ما العقوبة المنصوص عليها للتجاوز الممنوع؟","choix":[{"fr":"Jusqu'à 1 mois de prison et/ou une amende de 120 à 200 DT","ar":"السجن حتى شهر و/أو خطية من 120 إلى 200 دينار"},{"fr":"Une simple remarque","ar":"مجرد ملاحظة"},{"fr":"Retrait définitif du permis","ar":"سحب نهائي للرخصة"}],"bonnes":[0],"explication_fr":"Le dépassement interdit est un délit puni d'un emprisonnement d'un mois au maximum et d'une amende de 120 à 200 DT, ou de l'une de ces peines.","explication_ar":"التجاوز الممنوع جنحة يُعاقب عليها بالسجن مدة أقصاها شهر وبخطية من 120 إلى 200 دينار أو بإحدى العقوبتين.","source":"Code de la route, article 86 (alinéa 3, point 4)","image":"q-sanction-depassement.svg"},
{"id":"T10-011","theme":10,"question_fr":"Quelle est la peine prévue pour la conduite sans permis ?","question_ar":"ما العقوبة المنصوص عليها للسياقة دون رخصة؟","choix":[{"fr":"Jusqu'à 6 mois de prison et/ou une amende de 200 à 500 DT","ar":"السجن حتى 6 أشهر و/أو خطية من 200 إلى 500 دينار"},{"fr":"Une amende de 20 DT","ar":"خطية بـ 20 دينارًا"}],"bonnes":[0],"explication_fr":"La conduite sans permis ou sans la catégorie requise est un délit : 6 mois de prison au maximum et 200 à 500 DT d'amende, ou l'une de ces peines. Le véhicule est aussi immobilisé.","explication_ar":"السياقة دون رخصة أو دون الصنف المطلوب جنحة: السجن مدة أقصاها 6 أشهر وخطية من 200 إلى 500 دينار أو إحدى العقوبتين، كما يتم إيقاف العربة.","source":"Code de la route, articles 87 (point 2) et 105 (point 4)","image":"q-sans-permis.svg"},
{"id":"T10-012","theme":10,"question_fr":"Circuler en sens inverse ou faire demi-tour sur une autoroute (en traversant le terre-plein) entraîne :","question_ar":"السير في الاتجاه المعاكس أو الدوران على الطريق السيارة (بعبور الفاصل الأوسط) يؤدي إلى:","choix":[{"fr":"Un délit, le retrait du permis et la perte de 4 points","ar":"جنحة وسحب الرخصة وخسارة 4 نقاط"},{"fr":"Une simple contravention de 1re catégorie","ar":"مجرد مخالفة من الصنف الأول"}],"bonnes":[0],"explication_fr":"C'est un délit (6 mois de prison max et 200 à 500 DT), qui entraîne le retrait du permis (6 mois max la première fois) et un retrait de 4 points.","explication_ar":"هي جنحة (السجن حتى 6 أشهر وخطية من 200 إلى 500 دينار) تؤدي إلى سحب الرخصة (6 أشهر على الأكثر في المرة الأولى) وسحب 4 نقاط.","source":"Code de la route, articles 87 (point 3), 92 et 93 ; Décret n° 2000-144, article 3","image":"q-sens-inverse-autoroute.svg"},
{"id":"T10-014","theme":10,"question_fr":"Quel est l'âge minimum pour passer le permis de la catégorie B (voiture) ?","question_ar":"ما هو السن الأدنى لاجتياز امتحان رخصة السياقة صنف «ب» (سيارة)؟","choix":[{"fr":"16 ans","ar":"16 سنة"},{"fr":"18 ans","ar":"18 سنة"},{"fr":"21 ans","ar":"21 سنة"}],"bonnes":[1],"explication_fr":"L'âge minimum est de 18 ans pour les catégories A, B et H (16 ans pour A1, 20 ans pour C, D1 et B+E, 21 ans pour D, C+E et D+E).","explication_ar":"السن الأدنى 18 سنة للأصناف A وB وH (16 سنة لـ A1، و20 سنة لـ C وD1 وB+E، و21 سنة لـ D وC+E وD+E).","source":"Décret n° 2000-142, article 10","image":"q-age-permis.svg"}];
if (typeof module !== "undefined") module.exports = { QUESTIONS, QUESTIONS_INFO };
